# БАГФИКС (21.09.2026, "бот не показывает сообщение об обновлении бота после
# редеплоя"): раньше DB_FILE был просто 'taxi_queue.db' - относительный путь
# внутри контейнера. Если у сервиса в Railway НЕ подключён Persistent Volume
# (или подключён, но не смонтирован в рабочую директорию), при каждом
# редеплое файловая система контейнера пересоздаётся с нуля - вместе с ней
# теряется и bot_meta.last_deployed_commit (см. notify_users_about_new_deploy
# ниже), и бот каждый раз думает, что это первый запуск, поэтому пуш "бот
# обновился" никогда не отправляется (та же потеря касалась бы и user_states/
# истории смен/рефералов/подписок - всё в этом же файле). Стандартный путь
# монтирования Railway Volume - /data; если он существует и доступен на
# запись - используем его (файл переживёт редеплой), иначе тихо откатываемся
# на прежний путь в рабочей директории (тестовый/локальный запуск без volume
# по-прежнему работает, просто без сохранения между перезапусками).
def _resolve_db_file():
    railway_volume_dir = '/data'
    if os.path.isdir(railway_volume_dir) and os.access(railway_volume_dir, os.W_OK):
        return os.path.join(railway_volume_dir, 'taxi_queue.db')
    return 'taxi_queue.db'

DB_FILE = _resolve_db_file()
# По повторной жалобе пользователя (22.09.2026): "при редеплое всё слетает -
# город, категория, смена" - несмотря на фикс выше (_resolve_db_file), если
# в Railway НЕ подключён Persistent Volume (Settings -> Volumes -> Add Volume,
# Mount Path = /data), os.path.isdir('/data') просто вернёт False и БД тихо
# продолжит жить в обычной рабочей директории контейнера, которая
# пересоздаётся с нуля при КАЖДОМ редеплое - весь user_state (город/
# категория/смена) теряется, хотя сам код persistence уже написан правильно.
# Раньше это никак не логировалось, из-за чего проблему было не увидеть в
# логах Railway - теперь пишем явно, каким путём реально работает бот.
if DB_FILE.startswith('/data'):
    logger.info(f"✅ БД на постоянном Railway Volume: {DB_FILE} - состояние переживёт редеплой")
else:
    logger.warning(
        f"⚠️ БД НЕ на постоянном хранилище (путь: {DB_FILE}) - Railway Volume не подключён или не смонтирован "
        f"в /data. Город/категория/смена и вся остальная БД будут СБРАСЫВАТЬСЯ при каждом редеплое. "
        f"Чтобы исправить: в Railway -> сервис бота -> Settings -> Volumes -> Add Volume, Mount Path = /data."
    )
