def get_upcoming_concert_events_for_category(city, category, limit=10):
    """Предстоящие события афиши концертов для КОНКРЕТНОЙ категории водителя -
    по просьбе пользователя (22.09.2026): события с ценой >= PRICE_THRESHOLD_RUB
    (см. fetch_concert_events.py) показываются И такси, И Ultima
    (price_category='all'); дешевле/бесплатные/без указанной цены - ТОЛЬКО
    такси (price_category='taxi_only') - Ultima это не интересно. Курьер/
    Грузовое такси эту кнопку вообще не видят (см. CATEGORIES_WITHOUT_EVENTS),
    поэтому фильтр здесь рассчитан только на 'taxi'/'ultima'. Событие без
    распознанной даты (start=None - разметка поста не подошла под парсер)
    пропускается: без даты нельзя понять, актуально ли оно ещё.

    По прямому запросу пользователя (19.09.2026, ответы на AskUserQuestion):
    1) показываем события на СЕГОДНЯ И ЗАВТРА в местном времени города (не
       всю афишу на месяцы вперёд) - сравниваем календарную дату start с
       "сегодня"/"завтра" в часовом поясе города (тот же EVENT_CITY_TIMEZONE,
       которым размечены сами события в fetch_concert_events.py). Изначально
       было СТРОГО "только сегодня" (19.09.2026), но выяснилось, что в
       каналах часто вообще нет ни одного события именно на текущий день
       (особенно ночью/рано утром, пока новых постов на новый день ещё не
       было) - афиша получалась почти всегда пустой. Расширено до 2 дней
       (19.09.2026, повторная жалоба пользователя) - компромисс между "не
       завалить всей афишей на месяцы" и "не показывать пустой экран";
    2) события БЕЗ явно указанного в посте времени начала
       (start_has_explicit_time=False - у них start это заглушка 20:00 UTC,
       см. parse_event_datetime в fetch_concert_events.py) - НЕ исключаются
       полностью (так было раньше, но выяснилось, что у подавляющего
       большинства постов канала время вообще не указано - "18 ноября /
       Pravda / 1300 ₽" без часов - и афиша почти всегда получалась пустой),
       а показываются С ПОМЕТКОЙ "точное время не указано в афише" (см.
       build_concert_event_message) - как было изначально, ещё до этого
       фильтра. Отбор по дате (пункт 1) для таких событий делаем по
       заглушке start (20:00 UTC), что для сравнения календарной даты
       достаточно точно."""
    posts = get_concert_events_for_city(city)
    tz = ZoneInfo(EVENT_CITY_TIMEZONE.get(city, 'Europe/Moscow'))
    now_local = datetime.now(tz)
    allowed_dates = {now_local.date(), (now_local + timedelta(days=1)).date()}
    upcoming = []
    later = []  # события позже "завтра" - запасной вариант, см. ниже
    for post in posts:
        if not post.get('start'):
            continue
        try:
            start_dt = datetime.fromisoformat(post['start'])
        except Exception:
            continue
        start_local = start_dt.astimezone(tz)
        # Событие без явного времени пропускаем мимо проверки "уже прошло" -
        # заглушка 20:00 UTC не отражает реальное время, отсекать по ней
        # рискованно (можно скрыть ещё не начавшееся вечернее событие).
        if post.get('start_has_explicit_time') and start_local < now_local:
            continue
        if not post.get('start_has_explicit_time') and start_local.date() < now_local.date():
            continue
        price_category = post.get('price_category', 'taxi_only')
        if category == 'ultima' and price_category != 'all':
            continue
        if start_local.date() in allowed_dates:
            upcoming.append(post)
        elif start_local.date() > now_local.date():
            later.append(post)
    upcoming.sort(key=lambda p: p['start'])
    if upcoming:
        return upcoming[:limit]

    # По жалобе пользователя (20.09.2026, "события города опять пустые"):
    # если на сегодня/завтра в канале ничего нет (канал мог просто не
    # постить несколько дней - это данные, а не баг), не показываем пустой
    # экран - лучше честно показать ближайшие события ПОЗЖЕ, чем "завтра",
    # с явной пометкой в тексте (см. build_concert_event_message -
    # 'is_fallback_later'), чем оставить раздел без единого события.
    later.sort(key=lambda p: p['start'])
    return [dict(p, is_fallback_later=True) for p in later[:limit]]

