# Водители сами отмечают, сколько машин видят в очереди на аэропорту - выбором
# диапазона, а не точного числа (точно посчитать чужие машины в моменте
# нереально). Диапазоны по 5: 1-5, 6-10, ... 96-100.
QUEUE_RANGES = [(i, i + 4) for i in range(1, 101, 5)]

def queue_range_label(idx):
    lo, hi = QUEUE_RANGES[idx]
    return f"{lo}-{hi}"

def format_airport_local_time(utc_timestamp_str, airport_icao):
    """Время отметки в БД хранится как datetime.now() сервера (Railway работает
    в UTC), поэтому для показа пользователю его нужно перевести в местное
    время КОНКРЕТНОГО аэропорта - иначе увидим UTC вместо реального часа, тот
    же баг, что уже правили с расписанием рейсов."""
    try:
        naive = datetime.strptime(utc_timestamp_str, '%Y-%m-%d %H:%M:%S')
        aware_utc = naive.replace(tzinfo=ZoneInfo('UTC'))
        tz_name = AIRPORT_TIMEZONE.get(airport_icao, 'Europe/Moscow')
        local = aware_utc.astimezone(ZoneInfo(tz_name))
        return local.strftime('%H:%M')
    except Exception:
        return utc_timestamp_str

def _queue_airport_key(airport_icao, zone_key=None):
    """Ключ аэропорта в таблице queue - обычно просто icao, но для
    аэропортов с терминальными зонами (сейчас только Шереметьево/UUEE, см.
    AIRPORT_TERMINAL_ZONES) с суффиксом "#zone_key" - ИСПРАВЛЕНО 20.09.2026
    (по просьбе пользователя, вслед за разведением B/C и D на разные точки
    на карте): раньше отметки очереди у обеих терминальных зон писались под
    одним и тем же icao=UUEE и физически не различались - водитель,
    стоящий у Терминала D, видел (и портил) общую очередь Терминала B/C, и
    наоборот. Схема БД не менялась (колонка airport как была TEXT) - просто
    для зональных аэропортов туда пишется составной ключ. Старые
    отметки без суффикса (до этого фикса) просто перестают совпадать с
    новыми зональными запросами и угасают сами по TTL (QUEUE_ENTRY_TTL_MINUTES) -
    отдельная миграция не нужна."""
    return f"{airport_icao}#{zone_key}" if zone_key else airport_icao

def queue_submit_report(user_id, city, airport_icao, category, range_str, zone_key=None):
    """Сохраняет отметку водителя о длине очереди. Это не "встать в очередь" -
    просто разовый отчёт "я сейчас вижу вот столько машин", поэтому старые
    отметки не удаляются при новой - копится история, из которой потом берём
    последние отметки для оценки."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'INSERT INTO queue (user_id, city, airport, tariff, position_range, timestamp) VALUES (?, ?, ?, ?, ?, ?)',
        (user_id, city, _queue_airport_key(airport_icao, zone_key), category, range_str,
         datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
    )
    conn.commit()
    conn.close()

def user_recent_queue_marks(user_id, city, airport_icao, zone_key=None):
    """Собственные СВЕЖИЕ (за QUEUE_ENTRY_TTL_MINUTES) отметки ЭТОГО водителя
    для этого аэропорта/терминала - {tariff: range_str}, самая свежая по
    каждому tariff. Добавлено 20.09.2026 по просьбе пользователя: "если он
    отметился в зоне аэропорта раз, второй раз можно уже не спрашивать" - на
    повторном пуше "давно рядом с аэропортом" (см. send_airport_queue_push)
    так можно предложить водителю просто подтвердить "я всё ещё тут" одной
    кнопкой (переотправить те же тарифы/диапазоны с новым временем), не
    заставляя заново проходить весь выбор тарифа и диапазона машин."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    cursor.execute(
        'SELECT tariff, position_range, timestamp FROM queue WHERE user_id = ? AND city = ? AND airport = ? '
        'AND timestamp >= ? ORDER BY timestamp ASC',
        (user_id, city, _queue_airport_key(airport_icao, zone_key), cutoff)
    )
    rows = cursor.fetchall()
    conn.close()
    marks = {}
    for tariff, range_str, ts in rows:
        marks[tariff] = range_str  # ASC порядок - последняя запись по каждому tariff перезапишет более раннюю
    return marks

def queue_latest_report(city, airport_icao, category, zone_key=None):
    """Последняя свежая отметка водителя (за QUEUE_ENTRY_TTL_MINUTES) - без
    усреднения, просто тот диапазон, который отметил последний водитель.
    Возвращает (range_str, timestamp) или (None, None), если свежих отметок нет."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    cursor.execute(
        'SELECT position_range, timestamp FROM queue WHERE city = ? AND airport = ? AND tariff = ? AND timestamp >= ? '
        'ORDER BY timestamp DESC LIMIT 1',
        (city, _queue_airport_key(airport_icao, zone_key), category, cutoff)
    )
    row = cursor.fetchone()
    conn.close()
    return row if row else (None, None)

def queue_latest_report_for_category(city, airport_icao, category, zone_key=None):
    """Как queue_latest_report, но БЕЗ привязки к конкретному тарифу - берёт
    самую свежую отметку любого водителя данной КАТЕГОРИИ (такси/Ultima/...)
    на аэропорту, независимо от того, какой именно тариф он указал
    (queue_class_key пишет tariff как "taxi:Комфорт+" и т.п., либо просто
    "taxi" без тарифа) - нужно для карты аэропортов (см.
    handle_map_airports_api), где нет смысла дробить по тарифам."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    airport_key = _queue_airport_key(airport_icao, zone_key)
    cursor.execute(
        'SELECT position_range, timestamp FROM queue WHERE city = ? AND airport = ? '
        'AND (tariff = ? OR tariff LIKE ?) AND timestamp >= ? '
        'ORDER BY timestamp DESC LIMIT 1',
        (city, airport_key, category, f'{category}:%', cutoff)
    )
    row = cursor.fetchone()
    conn.close()
    return row if row else (None, None)

bot = None
dp = Dispatcher()
router = Router()

# По просьбе пользователя (19.09.2026): "режим одного сообщения" - бот
# держит в чате только своё САМОЕ ПОСЛЕДНЕЕ сообщение, стирая предыдущее
# перед отправкой нового (вместо накопления истории кнопок/карточек).
# ИЗМЕНЕНО 21.09.2026 (просьба пользователя: "оставлял тока последних 2
# сообщения, остальное удалял, чтобы чисто в чате было") - теперь хранится
# НЕБОЛЬШАЯ ОЧЕРЕДЬ (KEEP_LAST_N_MESSAGES=2) id последних сообщений на чат
# вместо одного: перед отправкой нового сообщения удаляются ВСЕ сообщения
# в очереди, которые выйдут за пределы последних N ПОСЛЕ добавления нового
# (т.е. в чате всегда остаётся новое + (N-1) предыдущих).
# Реализовано ОДНИМ местом на уровне HTTP-запросов к Telegram API (aiogram
# request middleware), а не правкой каждого из ~285 мест с .answer() в
# коде бота - middleware перехватывает КАЖДЫЙ исходящий sendMessage, после
# отправки добавляет id нового сообщения в очередь чата и удаляет всё, что
# выпало за пределы KEEP_LAST_N_MESSAGES. Если удаление не удалось
# (сообщение уже стёрто пользователем, прошло >48ч и Telegram сам не даёт
# удалить, и т.п.) - тихо игнорируем, это не должно ломать отправку нового
# сообщения.
#
# ВАЖНО (баг найден 19.09.2026): сообщения с ReplyKeyboardMarkup (нижнее
# меню кнопок 8/8 и т.п.) НЕ удаляются и НЕ добавляются в очередь на
# удаление. В Telegram reply-клавиатура привязана к КОНКРЕТНОМУ сообщению
# чата, а не существует отдельно от него - если удалить то самое сообщение,
# у пользователя вместе с ним пропадает и нижнее меню, пока не придёт новое
# сообщение с клавиатурой. Поэтому такие сообщения (и учёт "что можно
# удалить" тоже) не участвуют в этой логике - они остаются в чате как
# обычно, стирается только всё остальное (карточки событий, текстовые
# ответы без меню и т.п).
KEEP_LAST_N_MESSAGES = 2
_recent_bot_message_ids = {}  # chat_id -> список последних message_id бота (без reply-клавиатуры), новые в конце

# ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя - "сделай так чтобы
# события грузились все бот не удалял и оставлял тока два последних"): по
# умолчанию KEEP_LAST_N_MESSAGES=2 стирает ВСЕ сообщения бота без разбора,
# включая карточки афиши ("🎭 События города" - до 20 отдельных сообщений
# одно за другим), из-за чего в чате оставались только 2 последние карточки,
# а остальные исчезали почти сразу после отправки. Нужно исключение именно
# для этого экрана - карточки событий должны оставаться в чате все, не
# участвуя в общей чистке. Реализовано через contextvar (а не отдельным
# параметром у каждого из ~285 message.answer() в файле): хендлер, который
# шлёт события, оборачивает свою рассылку в _skip_message_trim.set(True)/
# reset(token), а middleware ниже читает этот флаг перед каждой отправкой -
# сообщения, отправленные внутри такого блока, не попадают в очередь на
# удаление вообще (та же ветка, что уже была у сообщений с ReplyKeyboardMarkup).
_skip_message_trim = contextvars.ContextVar('skip_message_trim', default=False)

class SingleMessageMiddleware(BaseRequestMiddleware):
    async def __call__(self, make_request, bot_instance: Bot, method: TelegramMethod[TelegramType]):
        if isinstance(method, SendMessage):
            chat_id = method.chat_id
            has_reply_keyboard = isinstance(method.reply_markup, ReplyKeyboardMarkup)
            skip_trim = _skip_message_trim.get()
            result = await make_request(bot_instance, method)
            try:
                if has_reply_keyboard or skip_trim:
                    # Сообщение с нижним меню, ИЛИ сообщение, отправленное
                    # внутри блока с отключённой чисткой (см. _skip_message_trim
                    # выше) - не трогаем и не добавляем в очередь на удаление.
                    pass
                else:
                    queue = _recent_bot_message_ids.setdefault(chat_id, [])
                    queue.append(result.message_id)
                    save_recent_bot_message(chat_id, result.message_id)
                    # Удаляем всё, что выпало за пределы последних KEEP_LAST_N_MESSAGES
                    while len(queue) > KEEP_LAST_N_MESSAGES:
                        old_id = queue.pop(0)
                        delete_recent_bot_message_row(chat_id, old_id)
                        try:
                            await bot_instance.delete_message(chat_id=chat_id, message_id=old_id)
                        except Exception:
                            pass  # сообщение уже удалено/недоступно для удаления - не критично
            except Exception:
                pass
            return result
        return await make_request(bot_instance, method)

async def initialize_bot():
    global bot
    try:
        logger.info("📡 Инициализирую бота...")
        bot = Bot(token=BOT_TOKEN)
        bot.session.middleware(SingleMessageMiddleware())
        me = await bot.get_me()
        logger.info(f"✅ Бот: @{me.username}")
        # На боте где-то раньше (вручную или другим запуском) был включён
        # webhook - Telegram не даёт одновременно webhook и getUpdates
        # (polling, см. dp.start_polling ниже), из-за чего в логах Railway
        # сыпался TelegramConflictError "can't use getUpdates method while
        # webhook is active". Снимаем webhook явно при каждом старте - если
        # его и не было, вызов просто ничего не делает (безопасно вызывать
        # всегда), а если был - синхронизирует бота обратно на polling.
        try:
            webhook_info = await bot.get_webhook_info()
            if webhook_info.url:
                logger.warning(f"⚠️ Обнаружен активный webhook ({webhook_info.url}) - удаляю, бот работает через polling")
                await bot.delete_webhook(drop_pending_updates=False)
                logger.info("✅ Webhook удалён")
        except Exception as e:
            logger.error(f"❌ Не удалось проверить/удалить webhook: {e}")
        return True
    except Exception as e:
        logger.error(f"❌ Ошибка: {e}")
        return False

