# пассажиров с рейсов) - кнопка "Аэропорты" им не показывается вообще.
CATEGORIES_WITHOUT_AIRPORTS = {'courier', 'cargo'}

# Внешний бот "Где бензин" (@gde_benzin_rubot) - народная карта наличия
