@router.callback_query(lambda c: c.data.startswith('peak_day_'))
async def switch_peak_hours_day(callback_query: types.CallbackQuery):
    """Переключение дня недели на экране "Часы пика" - перерисовывает то же
    сообщение (edit_text), без "Сейчас: ..." строки (она осмысленна только
    для текущего реального дня, см. format_peak_hours_text). callback_data -
    "peak_day_{0-6}" (такси/Ultima) или "peak_day_{0-6}_{category}"
    (courier/cargo - своя таблица часов пика, см.
    peak_hours_weekday_keyboard) - category берём из callback_data, а не из
    user_state, чтобы переключение дней недели корректно работало даже если
    пользователь сменил категорию, не закрывая старое сообщение "Часы пика"."""
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    if not city:
        await callback_query.answer("Начни заново с /start", show_alert=True)
        return
    parts = callback_query.data.split('_')
    weekday = int(parts[2])
    category = parts[3] if len(parts) > 3 else None
    if weekday < 0 or weekday > 6:
        await callback_query.answer("Ошибка!", show_alert=True)
        return
    text = format_peak_hours_text(city, target_weekday=weekday, category=category)
    keyboard = peak_hours_weekday_keyboard(weekday, category=category)
    await callback_query.message.edit_text(text, reply_markup=keyboard, parse_mode='Markdown')
    await callback_query.answer()

# ==================== "КУДА ЕХАТЬ" (сводная рекомендация) ====================
# Пока ТОЛЬКО для такси/Ultima (см. courier_module_keyboard - кнопка скрыта
# для CATEGORIES_WITHOUT_AIRPORTS). Сравнивает несколько "кандидатов" -
# каждый аэропорт города и обобщённый "Город/центр" - по условному баллу
# спроса, собранному из уже существующих источников данных бота:
#   - аэропорт: загрузка прилётов ПРЯМО СЕЙЧАС (compute_current_availability),
#     статус Росавиации (get_airport_status - штраф, если закрыт/по
#     согласованию) и живая очередь у аэропорта (queue_latest_report по ЛЮБОМУ
#     тарифу - штраф, если очередь уже большая, даже при высокой загрузке)
#   - "Город/центр": уровень часа пика (get_current_peak_level) + бонус за
#     дождь/снег (weathercode из fetch_rain_forecast, тот же источник, что
#     уже используется для пуш-уведомлений о дожде)
# Разные единицы измерения (% загрузки аэропорта vs уровень пика города) -
# ЗНАЧИТ, это не физически точный расчёт, а понятный водителю ориентир с
# объяснением "почему" - как и WEEKDAY_HOUR_LOAD выше, ориентир, не прогноз.
# "Длинная" очередь для целей этого скоринга - от 21 машины (5-й диапазон
# QUEUE_RANGES и дальше). Строится из самого QUEUE_RANGES, а не захардкожена
# отдельным списком строк - чтобы не разъехаться, если шаг/границы диапазонов
# когда-нибудь изменятся (см. QUEUE_RANGES выше по файлу).
WHERE_TO_GO_QUEUE_LONG_RANGES = {f'{lo}-{hi}' for lo, hi in QUEUE_RANGES if lo >= 21}

def pluralize_ru(n, one, few, many):
    """Русское склонение по числу: 1 рейс / 2 рейса / 5 рейсов. Стандартное
    правило падежей (11-14 - всегда "many", иначе по последней цифре)."""
    n_abs = abs(n)
    if 11 <= n_abs % 100 <= 14:
        return many
    last = n_abs % 10
    if last == 1:
        return one
    if 2 <= last <= 4:
        return few
    return many

def score_station_candidate(city, code, station, category):
    """Балл и обоснование для одного вокзала города - тот же принцип, что
    score_airport_candidate, но на бинарной шкале вокзалов (см.
    get_train_load_symbol/get_train_load_label) вместо 4-уровневой шкалы
    аэропортов. По просьбе пользователя (21.09.2026) вокзалы тоже участвуют
    в "Куда ехать", а не только аэропорты. score - тот же % загрузки
    текущего получаса, что показывается на кнопке вокзала в разделе
    "✈️🚆 Авиа/ЖД" - шкалы сопоставимы (обе - % от часовой ёмкости),
    прямое сравнение с score аэропорта корректно."""
    load, trains_in_period, _ = compute_current_train_period_load(code, category)
    reasons = []
    if trains_in_period > 0:
        train_word = pluralize_ru(trains_in_period, "поезд", "поезда", "поездов")
        reasons.append(f"{trains_in_period} {train_word} в этот получас")
    else:
        reasons.append("прибытий в этот получас нет")
    label = get_train_load_label(load)
    if label == 'ЕХАТЬ':
        reasons.append("стоит подъехать")
    return {'label': f"🚆 {station['name']}", 'score': load, 'reasons': reasons, 'closed': False, 'advice': None}

async def score_airport_candidate(city, airport, category):
    """Считает балл и обоснование для одного аэропорта города. Возвращает
    dict {label, score, reasons: [str, ...], closed: bool}. relevant_class -
    та же логика, что CATEGORY_TO_CLASS в остальном боте (эконом/бизнес/все)."""
    icao = airport['icao']
    zone_key = airport.get('zone_key')
    relevant_class = CATEGORY_TO_CLASS.get(category, 'total')
    reasons = []

    status, _notice = get_airport_status(icao)
    if airport.get('closed') or status == 'closed':
        return {'label': airport['name'], 'score': -1000, 'reasons': ['аэропорт закрыт'], 'closed': True, 'advice': None}

    avail = compute_current_availability(icao, relevant_class, zone_key=zone_key)
    score = avail['load']  # базовый балл - % загрузки прилётов на текущий час
    n_flights = len(avail['arrivals_now'])
    if n_flights > 0:
        flight_word = pluralize_ru(n_flights, "рейс", "рейса", "рейсов")
        reasons.append(f"{n_flights} {flight_word} в этот час")
    else:
        reasons.append("прилётов в этот час нет")

    if status == 'coordinated':
        score *= 0.7
        reasons.append("работает по согласованию")

    # Очередь - берём самую свежую отметку СРЕДИ ВСЕХ тарифов этой категории
    # на этом аэропорту (а не только тарифа, который сейчас выбран у
    # пользователя) - для сводки "куда ехать" важна общая картина, не
    # конкретный класс. Ключ в БД - НЕ просто название тарифа, а
    # "{category}:{tariff}" (см. queue_class_key) - без category без
    # тарифа тоже проверяем (вдруг отмечали без выбора конкретного тарифа).
    tariffs = CATEGORIES.get(category, {}).get('tariffs') or []
    class_keys = {category} | {f"{category}:{t}" for t in tariffs}
    worst_range = None
    for class_key in class_keys:
        range_str, _ts = queue_latest_report(city, icao, class_key, zone_key=zone_key)
        if range_str in WHERE_TO_GO_QUEUE_LONG_RANGES:
            worst_range = range_str
            break
    if worst_range:
        score *= 0.6
        reasons.append(f"уже большая очередь ({worst_range} машин)")

    return {'label': airport['name'], 'score': score, 'reasons': reasons, 'closed': False, 'advice': None}

# Развёрнутая рекомендация по типам заведений для "Город/центр" - по
# просьбе пользователя (21.09.2026): просто "повышенный спрос" мало что
# говорит водителю, нужен конкретный совет КУДА именно в центре ехать/
# держаться, в зависимости от дня недели и текущего уровня спроса. Пятница/
# суббота вечер-ночь - ночная жизнь (клубы/бары/рестораны/стриптиз-клубы),
# будни вечер - рестораны/бары после работы, будни утро/день - деловой
# центр/офисы/ТЦ. Формулировки водитель дал сам (пятница-суббота = ночная
# жизнь, будни = обычный деловой трафик) - остальное подобрано по аналогии,
# не строгий факт, а ориентир ("держись центра и этих заведений").
_CITY_ADVICE_WEEKEND_NIGHT = (
    "ночь клубов, баров и ресторанов - держись центра и заведений ночной "
    "жизни (клубы, бары, рестораны, стриптиз-клубы): люди разъезжаются "
    "поздно и часто берут такси именно от входа"
)
_CITY_ADVICE_WEEKEND_EVENING = (
    "вечер пятницы/субботы - люди едут в центр в рестораны, бары и клубы: "
    "держись районов с заведениями, спрос будет расти к ночи"
)
_CITY_ADVICE_WORKDAY_EVENING = (
    "вечер буднего дня - спрос из бизнес-центров/офисов и ресторанов/баров "
    "после работы, держись делового центра"
)
_CITY_ADVICE_WORKDAY_PEAK = (
    "час пик буднего дня - основной поток из жилых районов в центр/офисы "
    "(или обратно вечером), держись крупных транспортных направлений"
)
_CITY_ADVICE_DEFAULT = "держись центра города и оживлённых районов"

# Свои советы "куда именно держаться" для Курьера/Грузового такси (по
# просьбе пользователя, 20.09.2026 - "Куда ехать" для этих категорий
# строится на своих правилах: обед/ужин для курьера, рабочие часы бизнеса
# для грузового такси - см. CATEGORY_WEEKDAY_HOUR_LOAD выше). Развёрнутый
# совет по конкретным местам, не просто "спрос выше/ниже".
_COURIER_ADVICE_LUNCH = (
    "обеденный пик - держись у бизнес-центров, офисов и ТЦ с фудкортами, "
    "много заказов на доставку обеда"
)
_COURIER_ADVICE_DINNER = (
    "вечерний пик - основной поток из жилых районов, держись рядом с "
    "популярными ресторанами/тёмными кухнями и плотной жилой застройкой"
)
_COURIER_ADVICE_LATE_NIGHT = (
    "поздняя ночь пятницы/субботы/воскресенья - доходный отрезок после "
    "баров и вечеринок, держись рядом с ночными заведениями и клубами"
)
_COURIER_ADVICE_WEEKEND_DAY = (
    "выходной день - спрос выше обычного будня весь день (не только в "
    "обед/ужин), держись жилых районов и заведений с доставкой"
)
_COURIER_ADVICE_DEFAULT = "держись районов с высокой плотностью кафе/ресторанов и жилой застройки"

_CARGO_ADVICE_PEAK = (
    "рабочий пик - держись рядом с логистическими центрами, складами, "
    "оптовыми базами и промзонами, много заявок на перевозку грузов"
)
_CARGO_ADVICE_WORKDAY = "рабочее время - держись деловых районов и складских зон"
_CARGO_ADVICE_WEEKEND_PEAK = (
    "пик переездов и вывоза мебели/техники - держись жилых районов, ТЦ с "
    "мебелью/бытовой техникой и новостроек, где люди заезжают"
)
_CARGO_ADVICE_WEEKEND_DAY = "выходной - в основном частные переезды и перевозка крупных покупок, держись жилых районов"
_CARGO_ADVICE_DEFAULT = "сейчас спрос низкий - заявок будет немного"

def get_cargo_advice(level, is_weekend):
    if is_weekend:
        if level == 'peak':
            return _CARGO_ADVICE_WEEKEND_PEAK
        if level == 'high':
            return _CARGO_ADVICE_WEEKEND_DAY
        return _CARGO_ADVICE_DEFAULT
    if level == 'peak':
        return _CARGO_ADVICE_PEAK
    if level in ('mid', 'high'):
        return _CARGO_ADVICE_WORKDAY
    return _CARGO_ADVICE_DEFAULT

def get_city_advice(city, level, category=None):
    """Развёрнутый совет ПО ТИПАМ ЗАВЕДЕНИЙ для "Город/центр", в зависимости
    от дня недели (местное время города) и текущего уровня спроса. См.
    комментарий у _CITY_ADVICE_* выше про логику. weekday 4=пятница,
    5=суббота, 6=воскресенье (как в get_city_now().weekday()). category -
    для courier/cargo использует свои советы (обед/ужин + доходные пт/сб/вс
    для курьера, get_cargo_advice для грузового) вместо таксишной логики
    ночь/будни/выходные, т.к. паттерн спроса у них принципиально другой
    (см. CATEGORY_WEEKDAY_HOUR_LOAD - у обеих категорий пятница/суббота/
    воскресенье теперь отдельные доходные дни, по просьбе пользователя,
    20.09.2026)."""
    if category == 'courier':
        now = get_city_now(city)
        weekday = now.weekday()
        hour = now.hour
        is_weekend = weekday in (4, 5, 6)
        if is_weekend and (hour < 2 or hour >= 23):
            return _COURIER_ADVICE_LATE_NIGHT
        if level == 'peak' and 11 <= hour < 15:
            return _COURIER_ADVICE_LUNCH
        if level == 'peak':
            return _COURIER_ADVICE_DINNER
        if is_weekend and level == 'high':
            return _COURIER_ADVICE_WEEKEND_DAY
        return _COURIER_ADVICE_DEFAULT
    if category == 'cargo':
        now = get_city_now(city)
        is_weekend = now.weekday() in (4, 5, 6)
        return get_cargo_advice(level, is_weekend)

    now = get_city_now(city)
    weekday = now.weekday()
    hour = now.hour
    # Ночная зона пятницы/субботы переходит через полночь на следующий день
    # недели (пятница ночью -> уже суббота, суббота ночью -> уже
    # воскресенье) - поэтому проверяем ЧАСЫ ПОСЛЕ полуночи (hour < 4) у
    # СЛЕДУЮЩЕГО дня (5=суббота, 6=воскресенье), а не у самого (4,5).
    is_weekend_night_zone = (
        (weekday in (4, 5) and hour >= 22) or
        (weekday in (5, 6) and hour < 4)
    )
    is_weekend_evening = weekday in (4, 5) and 18 <= hour < 22
    if is_weekend_night_zone:
        return _CITY_ADVICE_WEEKEND_NIGHT
    if is_weekend_evening:
        return _CITY_ADVICE_WEEKEND_EVENING
    if weekday <= 3:  # будни (пн-чт)
        if level == 'peak':
            return _CITY_ADVICE_WORKDAY_PEAK
        if hour >= 18:
            return _CITY_ADVICE_WORKDAY_EVENING
    return _CITY_ADVICE_DEFAULT

async def score_city_candidate(city, category=None):
    """Балл для обобщённого "Город/центр" - на основе часа пика + погоды.
    Единицы условные (не %, как у аэропортов) - подобраны так, чтобы часы
    пика были заметно приоритетнее аэропорта со средней загрузкой, а низкий
    спрос - явно ниже почти любого аэропорта с прилётами. category -
    courier/cargo используют свою таблицу часов пика (см.
    get_current_peak_level/CATEGORY_WEEKDAY_HOUR_LOAD)."""
    level = get_current_peak_level(city, category=category)
    level_score = {'low': 10, 'mid': 40, 'high': 70, 'peak': 100}[level]
    reasons = [PEAK_LEVEL_LABEL[level]]

    score = level_score
    forecast = await fetch_rain_forecast(city)
    if forecast:
        current = forecast.get('current', {})
        code = current.get('weathercode')
        if code in PRECIP_WEATHERCODES:
            _name, weight, emoji = describe_weathercode(code)
            bonus = weight * 8  # вес 1-8 -> бонус 8-64 баллов
            score += bonus
            reasons.append(f"{emoji} осадки сейчас - спрос выше обычного")

    advice = get_city_advice(city, level, category=category)
    return {'label': 'Город / центр', 'score': score, 'reasons': reasons, 'closed': False, 'advice': advice}

# Концертное событие начинает давать всплеск спроса ЗА CONCERT_EVENT_LEAD_HOURS
# часов до начала (люди подъезжают заранее) и ОСТАЁТСЯ актуальным ещё
# CONCERT_EVENT_TAIL_HOURS часов после заявленного окончания (расходятся не
# все разом) - за пределами этого окна событие не показываем кандидатом в
# "Куда ехать" вообще (см. score_concert_event_candidates ниже).
CONCERT_EVENT_LEAD_HOURS = 1
CONCERT_EVENT_TAIL_HOURS = 1

def score_concert_event_candidates(city, category, limit=3):
    """Кандидаты "Куда ехать" на основе афиши концертов (см.
    get_upcoming_concert_events_for_category) - по просьбе пользователя
    (22.09.2026). Показываем только события, которые СЕЙЧАС релевантны по
    времени (см. CONCERT_EVENT_LEAD_HOURS/TAIL_HOURS выше), не всю афишу -
    иначе список "Куда ехать" был бы забит мероприятиями через неделю.
    Балл выше для события, которое вот-вот начнётся/только что началось
    (момент максимального наплыва - и подвоза, и разъезда), чем для того,
    что скоро закончится. Единицы условные, той же шкалы, что у
    score_city_candidate (peak=100), чтобы конкретное крупное событие могло
    обгонять общий уровень "Город/центр", но не обгоняло автоматически
    любой аэропорт с реальными прилётами."""
    events = get_upcoming_concert_events_for_category(city, category, limit=20)
    now_ts = datetime.now(ZoneInfo('UTC')).timestamp()
    candidates = []
    for post in events:
        try:
            start_ts = datetime.fromisoformat(post['start']).timestamp()
            end_ts = datetime.fromisoformat(post['end']).timestamp() if post.get('end') else start_ts
        except Exception:
            continue
        window_start = start_ts - CONCERT_EVENT_LEAD_HOURS * 3600
        window_end = end_ts + CONCERT_EVENT_TAIL_HOURS * 3600
        if not (window_start <= now_ts <= window_end):
            continue  # ещё рано или уже неактуально - не показываем кандидатом
        if now_ts < start_ts:
            score = 90  # скоро начнётся - подвоз гостей
        elif now_ts <= end_ts:
            score = 70  # мероприятие идёт - спрос ровнее, чем на входе/выходе
        else:
            score = 95  # уже закончилось (в пределах "хвоста") - самый пик разъезда
        reasons = ["мероприятие по афише"]
        if post.get('place'):
            reasons.append(post['place'])
        label = f"🎤 {post.get('title') or 'Мероприятие'}"
        candidates.append({'label': label, 'score': score, 'reasons': reasons, 'closed': False, 'advice': None})
    candidates.sort(key=lambda c: c['score'], reverse=True)
    return candidates[:limit]

async def compute_where_to_go(city, category):
    """Считает и сортирует всех кандидатов (аэропорты + вокзалы + актуальные
    события афиши + "Город/центр") по баллу - возвращает список dict от
    score_airport_candidate/score_station_candidate/score_concert_event_candidates/
    score_city_candidate, отсортированный по убыванию score, закрытые
    аэропорты (score=-1000) уходят в конец списка. Вокзалы добавлены по
    просьбе пользователя (21.09.2026) - только для городов из TRAIN_CITIES
    (см. STATION_CITY). Афиша концертов добавлена по просьбе пользователя
    (22.09.2026) - только события, актуальные ПРЯМО СЕЙЧАС (см.
    score_concert_event_candidates), не более 3, чтобы не забивать список.

    Курьер/Грузовое такси (20.09.2026): аэропорты, вокзалы и афиша концертов
    им не релевантны (это про пассажирские поездки с рейсов/на мероприятия) -
    для этих категорий единственный кандидат - "Город/центр", но посчитанный
    по СВОЕЙ таблице часов пика и советам (см. score_city_candidate/
    get_city_advice, category передаётся туда)."""
    if category in CATEGORIES_WITHOUT_AIRPORTS:
        return [await score_city_candidate(city, category=category)]

    # Каждый источник кандидатов обёрнут в свой try/except (по факту бага
    # 21.09.2026: "Не удалось посчитать варианты" стабильно на каждое
    # нажатие "КУДА ЕХАТЬ" - раньше ЛЮБОЕ исключение в ОДНОМ аэропорту/
    # вокзале/источнике роняло ВСЮ сводку, хотя остальные кандидаты
    # считались нормально. Теперь сбойный источник просто пропускается (с
    # логом полного traceback - см. logger.exception, а не только str(e), -
    # чтобы при следующей похожей ошибке сразу было видно причину), а не
    # берёт с собой всю фичу. "Город/центр" в конце - последняя надежда:
    # если он тоже упадёт, тогда уже показываем пользователю общую ошибку
    # (см. send_where_to_go), это по-прежнему возможно, но теперь только
    # когда сломано действительно всё, а не один источник."""
    candidates = []
    for airport in AIRPORTS_INFO.get(city, []):
        # Как и в ICAO_TO_AIRPORT - у Шереметьево несколько зональных записей
        # с одним icao (B/C и D), каждая - самостоятельный кандидат (разная
        # загрузка по зоне), дедуп не нужен, в отличие от ICAO_TO_AIRPORT.
        try:
            candidates.append(await score_airport_candidate(city, airport, category))
        except Exception:
            logger.exception(f"❌ Не удалось посчитать кандидата 'Куда ехать' для аэропорта {airport.get('icao')} ({city})")
    if city in TRAIN_CITIES:
        try:
            trains_data = load_trains_data()
            if trains_data and trains_data.get('stations'):
                city_stations = {code: st for code, st in trains_data['stations'].items() if STATION_CITY.get(code) == city}
                for code, station in city_stations.items():
                    try:
                        candidates.append(score_station_candidate(city, code, station, category))
                    except Exception:
                        logger.exception(f"❌ Не удалось посчитать кандидата 'Куда ехать' для вокзала {code} ({city})")
        except Exception:
            logger.exception(f"❌ Не удалось загрузить вокзалы для 'Куда ехать' ({city})")
    try:
        candidates.extend(score_concert_event_candidates(city, category))
    except Exception:
        logger.exception(f"❌ Не удалось посчитать афишу для 'Куда ехать' ({city})")
    # "Город/центр" тоже обёрнут в try/except (по факту повторной жалобы
    # пользователя, 21.09.2026: ошибка "Не удалось посчитать варианты"
    # продолжала стабильно повторяться для Такси Ultima в Москве даже
    # ПОСЛЕ того как остальные источники выше уже были защищены - то есть
    # реальная причина была именно здесь, в этом последнем, единственном
    # НЕзащищённом вызове). Раньше комментарий говорил "последняя надежда,
    # если и он упадёт - покажем общую ошибку" - но раз он падал каждый
    # раз, лучше не ронять всю сводку, а просто остаться без карточки
    # "Город/центр": compute_where_to_go в худшем случае вернёт кандидатов
    # только из аэропортов/вокзалов/афиши (или вообще пустой список -
    # format_where_to_go_text уже умеет корректно показать "нет данных" в
    # этом случае, не падая).
    try:
        candidates.append(await score_city_candidate(city, category=category))
    except Exception:
        logger.exception(f"❌ Не удалось посчитать кандидата 'Город/центр' для 'Куда ехать' ({city}/{category})")
    candidates.sort(key=lambda c: c['score'], reverse=True)
    return candidates

# Ранговые эмодзи для мест в списке "Остальные варианты" - по просьбе
# пользователя сделать сводку "красочнее" (21.09.2026): медаль для топ-3,
# дальше нейтральная точка. WHERE_TO_GO_RANK_EMOJI - медали 2 и 3 места
# (1 место уже показано отдельным блоком "Сейчас лучше всего" с 🏆).
WHERE_TO_GO_RANK_EMOJI = ['🥈', '🥉']

def _where_to_go_score_bar(score):
    """Условная визуальная шкала загрузки под score (0-100%+) - просто
    заполненность кружками, чисто декоративно (не привязана к 4-уровневой
    шкале аэропортов, т.к. у "Города" и вокзалов другие единицы/диапазоны).
    5 сегментов, каждый ~20 очков, максимум забивается на 5-м."""
    filled = min(5, max(0, round(score / 20)))
    return '●' * filled + '○' * (5 - filled)

WHERE_TO_GO_DIVIDER = "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄"

def format_where_to_go_text(city, category, candidates, extra_header=None):
    """extra_header - по просьбе пользователя (20.09.2026): позволяет
    встроить сообщение "СМЕНА НАЧАТА" прямо в начало сводки "Куда ехать"
    (см. toggle_shift), одним сообщением вместо двух отдельных.

    Визуальное оформление обновлено по просьбе пользователя (20.09.2026,
    "сделай красивое оформление") - точечный разделитель вместо сплошной
    линии (легче читается), топ-вариант в рамке из ▓, компактные блоки без
    лишних пустых строк между заголовком и содержимым."""
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    now = get_city_now(city)
    lines = []
    if extra_header:
        lines.append(extra_header)
        lines.append(WHERE_TO_GO_DIVIDER)
    lines.extend([
        f"🧭 *КУДА ЕХАТЬ · {city_name.upper()}*",
        f"🕐 {now.strftime('%H:%M')} · {WEEKDAY_NAMES[now.weekday()]}",
    ])

    open_candidates = [c for c in candidates if not c['closed']]
    if not open_candidates:
        lines.append(WHERE_TO_GO_DIVIDER)
        lines.append("⛔ Все аэропорты города сейчас закрыты - ориентируйся на центр города и часы пика (см. «📅 Часы пика»).")
        return '\n'.join(lines)

    best = open_candidates[0]
    reasons_str = ', '.join(best['reasons'])
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")
    lines.append(f"🏆 *{best['label']}*")
    lines.append(f"{_where_to_go_score_bar(best['score'])}  {reasons_str}")
    if best.get('advice'):
        lines.append(f"💡 {best['advice'][0].upper()}{best['advice'][1:]}.")
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")

    if len(open_candidates) > 1:
        lines.append("")
        lines.append("*Остальные варианты:*")
        for i, c in enumerate(open_candidates[1:]):
            rank_emoji = WHERE_TO_GO_RANK_EMOJI[i] if i < len(WHERE_TO_GO_RANK_EMOJI) else '▫️'
            lines.append("")
            lines.append(f"{rank_emoji} *{c['label']}*")
            lines.append(f"{_where_to_go_score_bar(c['score'])}  {', '.join(c['reasons'])}")
            # "Город/центр" не всегда занимает 1 место, но развёрнутый совет
            # по заведениям (см. get_city_advice) важен водителю в любом
            # случае - показываем его и здесь, а не только когда "Город"
            # лучший вариант (по просьбе пользователя, 21.09.2026: совет
            # пропадал, если аэропорт набирал больше баллов).
            if c.get('advice'):
                lines.append(f"💡 _{c['advice'][0].upper()}{c['advice'][1:]}._")

    closed = [c for c in candidates if c['closed']]
    if closed:
        lines.append(WHERE_TO_GO_DIVIDER)
        lines.append("⛔ *Закрыто сейчас:* " + ', '.join(c['label'] for c in closed))

    # По просьбе пользователя (19.09.2026): "оценка перекрытий" - число
    # активных перекрытий в городе (тот же источник, что "⛔ Дорожные
    # события" - is_closure, см. fetch_road_events.py) добавлено сюда общим
    # предупреждением, БЕЗ привязки к конкретному аэропорту/вокзалу/месту -
    # по тексту поста нельзя надёжно понять, у какого именно места
    # перекрытие, так что это просто общий сигнал "сейчас в городе неспокойно
    # на дорогах", а не часть расчёта score конкретного варианта.
    closures_count = count_active_road_closures(city)
    if closures_count:
        lines.append(WHERE_TO_GO_DIVIDER)
        word = "перекрытие" if closures_count == 1 else ("перекрытия" if 2 <= closures_count <= 4 else "перекрытий")
        lines.append(f"🚧 Сейчас в городе {closures_count} активных {word} - см. «⛔ Дорожные события».")

    lines.append(WHERE_TO_GO_DIVIDER)
    if category == 'courier':
        lines.append(
            "_Ориентир по часам активных заказов доставки еды - не гарантия "
            "заработка, реальный спрос может отличаться._"
        )
    elif category == 'cargo':
        lines.append(
            "_Ориентир по рабочим часам бизнеса и складов - не гарантия "
            "заработка, реальный спрос может отличаться._"
        )
    else:
        lines.append(
            "_Ориентир на основе прилётов, статуса аэропортов, очереди и часов "
            "пика - не гарантия заработка, реальный спрос может отличаться._"
        )
    return '\n'.join(lines)

_where_to_go_in_progress = set()  # user_id-ы, для которых сейчас уже считается сводка

async def send_where_to_go(message: types.Message, user_id, city, category, extra_header=None):
    """Общая логика сводки "Куда ехать" - вынесена из show_where_to_go, чтобы
    её же можно было вызвать программно сразу после начала смены (по просьбе
    пользователя, 20.09.2026), а не только по нажатию кнопки "💰 КУДА ЕХАТЬ".
    Не делает проверок города/категории - это ответственность вызывающего.
    extra_header - см. format_where_to_go_text (встраивает "СМЕНА НАЧАТА" в
    начало этого же сообщения, вместо отдельного - по просьбе пользователя,
    20.09.2026)."""
    # Защита от повторного нажатия, пока предыдущий запрос ещё считается
    # (баг 19.09.2026: двойной тап запускал два параллельных расчёта -
    # SingleMessageMiddleware удалял статус-сообщение ПЕРВОГО запроса при
    # отправке статус-сообщения ВТОРОГО, и последующий status_msg.edit_text
    # первого запроса падал на уже удалённом сообщении - без try/except это
    # тихо роняло всю задачу, и "Считаю варианты..." зависало навсегда).
    if user_id in _where_to_go_in_progress:
        return
    _where_to_go_in_progress.add(user_id)
    try:
        status_msg = await show_loading_animation(message.answer, "🧭 Считаю варианты")
        anim_task = asyncio.create_task(animate_loading(status_msg, "🧭 Считаю варианты"))
        try:
            candidates = await compute_where_to_go(city, category)
        except Exception:
            anim_task.cancel()
            # logger.exception (не просто logger.error с str(e)) - пишет
            # полный traceback в логи Railway, а не только текст исключения -
            # без этого при повторной похожей ошибке невозможно понять,
            # ГДЕ именно внутри compute_where_to_go она произошла (баг
            # 21.09.2026: "Не удалось посчитать варианты" стабильно на
            # каждое нажатие, но по одному str(e) причину было не найти).
            logger.exception(f"❌ Ошибка расчёта 'Куда ехать' для {city}/{category}")
            fallback_text = "⚠️ Не удалось посчитать варианты. Попробуй ещё раз через минуту."
            if extra_header:
                fallback_text = f"{extra_header}\n━━━━━━━━━━━━━━━━━━\n{fallback_text}"
            try:
                await status_msg.edit_text(fallback_text, parse_mode='Markdown' if extra_header else None)
            except Exception:
                await message.answer(fallback_text, parse_mode='Markdown' if extra_header else None)
            return
        anim_task.cancel()
        text = format_where_to_go_text(city, category, candidates, extra_header=extra_header)
        try:
            await status_msg.edit_text(text, parse_mode='Markdown')
        except Exception:
            # status_msg уже мог быть удалён (см. комментарий выше) -
            # отправляем результат новым сообщением, чтобы он точно дошёл.
            await message.answer(text, parse_mode='Markdown')
    finally:
        _where_to_go_in_progress.discard(user_id)

@router.message(lambda message: message.text == "💰 КУДА ЕХАТЬ ➡️")
async def show_where_to_go(message: types.Message):
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    category = state.get('category')
    if not city:
        await message.answer("Сначала выбери город 🏙")
        return
    # Курьер/Грузовое такси (20.09.2026): раньше кнопка была полностью
    # скрыта для этих категорий (не было аэропортов/прилётов, на которых
    # строилась сводка) - теперь у них есть своя версия "Куда ехать" (см.
    # compute_where_to_go/score_city_candidate: единственный кандидат
    # "Город/центр", посчитанный по своей таблице часов пика).
    await send_where_to_go(message, user_id, city, category)

@router.message(lambda message: message.text == "⚙️ Настройки")
async def show_notification_settings(message: types.Message):
    """"⚙️ Настройки" в главном меню (по просьбе пользователя, 19.09.2026,
    перенесена сюда из "Инструменты водителя", где была кнопкой
    "🔔 Уведомления"). Пока внутри только один раздел - настройка автопушей
    по типам (см. блок "НАСТРОЙКИ ПУШЕЙ" выше по файлу): каждый тип
    переключается отдельной инлайн-кнопкой (✅/☐), нажатие тоглит и
    перерисовывает клавиатуру на месте. Если в будущем добавятся другие
    настройки - здесь будет промежуточное меню."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    await message.answer(
        "🔔 *Уведомления*\n\nВыбери, какие пуши получать - нажми, чтобы включить/выключить:",
        reply_markup=notification_settings_keyboard(state, category),
        parse_mode='Markdown',
    )

@router.callback_query(lambda c: c.data.startswith("notif_toggle_") and c.data != "notif_toggle_airport_queue")
async def toggle_notification_setting(callback_query: types.CallbackQuery):
    await callback_query.answer()
    user_id = callback_query.from_user.id
    notif_key = callback_query.data[len("notif_toggle_"):]
    if notif_key not in NOTIFICATION_TYPES:
        return
    state = user_state[user_id]
    prefs = dict(state.get('notif_prefs') or {})
    prefs[notif_key] = not notifications_enabled(state, notif_key)
    state['notif_prefs'] = prefs
    await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, state.get('category')))

@router.callback_query(lambda c: c.data == "notif_toggle_airport_queue")
async def toggle_airport_queue_inline(callback_query: types.CallbackQuery):
    """Переключатель "📍 Очередь у аэропорта" внутри "⚙️ Настройки" (по
    просьбе пользователя, 19.09.2026 - перенесена сюда из "Инструменты
    водителя", где раньше была отдельной reply-кнопкой, см.
    toggle_airport_queue_tracking - та же логика влкл/выкл живой геопозиции,
    только теперь тоглится инлайн-кнопкой на месте, без ухода с экрана
    настроек). При первом включении показываем инструкцию по трансляции
    геопозиции отдельным сообщением (её нельзя уместить в подпись
    инлайн-кнопки)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    category = state.get('category')
    if category in CATEGORIES_WITHOUT_AIRPORTS:
        return
    if state.get('airport_queue_active'):
        state['airport_queue_active'] = False
        state['airport_queue'] = {}
        await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, category))
        await callback_query.message.answer("⏹ Отслеживание очереди у аэропорта остановлено.")
        return
    enable_airport_queue_tracking(user_id)
    await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, category))
    await callback_query.message.answer(airport_queue_enable_text(), parse_mode='Markdown')

# ==================== "СМЕНА" ====================
# По просьбе пользователя (20.09.2026, взамен более раннего варианта с
# отдельным переключателем "Счётчик км" в Настройках): кнопка "▶️ Начать
# смену" в главном меню (см. services_keyboard) одновременно запускает
# секундомер смены и счётчик пройденных км по живой геопозиции (та же
# трансляция, что и "Очередь у аэропорта" - Telegram шлёт обновления как
# edited_message.location, см. km_counter_ping ниже и общий фильтр
# _location_tracking_active рядом с хендлерами location). Кнопка меняется на
# "⏹ Завершить смену" - при нажатии показывает итог (время + км) и СРАЗУ
# сохраняет запись в таблицу shift_history (см. save_shift_record) для
# статистики за 6 месяцев в "💰 Финансы" (см. show_shift_stats).
#
# state['shift'] = {'started_at': iso, 'total_km': float, 'last_lat': float,
# 'last_lon': float} - есть шифт = смена идёт, отсутствует/None = не идёт.
SHIFT_MAX_JUMP_KM = 3.0  # скачок между двумя пингами больше этого - считаем сбоем GPS/потерей сигнала, км не прибавляем (просто обновляем точку)

def is_shift_active(state):
    return bool(state.get('shift'))

# Тарифы для выбора при начале смены (по прямой просьбе пользователя,
# 21.09.2026: "чтобы в начале смены он указывал в каких тарифах он будет
# работать" - можно выбрать несколько сразу, например Эконом+Комфорт).
# СВОЙ список тарифов под каждую категорию (по прямому уточнению
# пользователя, 21.09.2026: "нет смысла предлагать если человек выбрал
# ультима предлагай тарифы эконом комфорт... в такси ты пишешь эконом
# комфорт комфорт + минивэн... детский... Ультиме бизнес премьер Elite и
# круиз") - источник правды теперь CATEGORIES[category]['tariffs'] (те же
# тарифы, что и в остальном боте), а не отдельный общий список для всех.
def shift_tariff_options(category):
    """Список тарифов для выбора при старте смены КОНКРЕТНОЙ категории - см.
    CATEGORIES[category]['tariffs']. У cargo он пуст (нет смысла выбирать
    тариф грузовому такси) - для такой категории тарифный экран вообще не
    показывается, см. toggle_shift."""
    return CATEGORIES.get(category, {}).get('tariffs', [])

def shift_tariffs_keyboard(category, selected):
    """Инлайн-клавиатура выбора тарифов перед стартом смены - несколько
    можно выбрать одновременно (✅/☐, тоглятся на месте), внизу кнопка
    "▶️ Начать смену" подтверждает выбор. selected - set выбранных строк
    тарифа (из shift_tariff_options(category)); тариф идентифицируется по
    своему порядковому индексу в списке (callback_data), т.к. сами названия
    тарифов могут содержать пробелы/плюсы, неудобные для callback_data."""
    tariffs = shift_tariff_options(category)
    buttons = []
    for idx, label in enumerate(tariffs):
        mark = '✅' if label in selected else '☐'
        buttons.append([InlineKeyboardButton(text=f"{mark} {label}", callback_data=f"shift_tariff_toggle_{idx}")])
    buttons.append([InlineKeyboardButton(text="▶️ Начать смену", callback_data="shift_tariff_confirm")])
    return InlineKeyboardMarkup(inline_keyboard=buttons)

def format_shift_tariffs_label(tariffs):
    """"Эконом, Комфорт" - для подписи маркера на карте (см.
    map_webapp_html/handle_map_positions_api) и для текста сообщения
    "СМЕНА НАЧАТА". Тарифы уже человекочитаемые строки (см.
    CATEGORIES[category]['tariffs']) - просто склеиваем через запятую."""
    return ", ".join(tariffs)

def start_shift(user_id, tariffs=None):
    state = user_state[user_id]
    state['shift'] = {
        'started_at': datetime.now(timezone.utc).isoformat(), 'total_km': 0.0,
        'tariffs': list(tariffs or []),
    }

def km_counter_ping(user_id, lat, lon):
    """Обрабатывает один пинг живой геопозиции для счётчика км текущей смены -
    вызывается из тех же хендлеров location/edited_message, что и
    process_airport_queue_ping (независимо от неё - обе функции могут
    отрабатывать на один и тот же пинг, если у водителя одновременно идёт
    смена и включена очередь у аэропорта). Ничего не делает, если смена не
    идёт (see is_shift_active)."""
    state = user_state[user_id]
    shift = state.get('shift')
    if not shift:
        return
    shift = dict(shift)
    last_lat, last_lon = shift.get('last_lat'), shift.get('last_lon')
    if last_lat is not None and last_lon is not None:
        jump = haversine_km(last_lat, last_lon, lat, lon)
        if jump <= SHIFT_MAX_JUMP_KM:
            shift['total_km'] = shift.get('total_km', 0.0) + jump
    shift['last_lat'] = lat
    shift['last_lon'] = lon
    state['shift'] = shift

SHIFT_LONG_WARNING_HOURS = 12  # после скольких часов за рулём слать предупреждающий пуш (по просьбе пользователя, 20.09.2026)
SHIFT_LONG_WARNING_CHECK_MINUTES = 10  # как часто фоновая задача проверяет длительность активных смен

# По просьбе пользователя (20.09.2026): "сделай так чтобы смена автоматически
# завершалась после 18 часов секундомера ведь юзер может забыть" - за
# SHIFT_AUTO_FINISH_WARN_MINUTES до лимита шлём предупреждение "смена скоро
# завершится автоматически" (флаг warned_auto_finish, тот же принцип
# дедупа, что warned_12h), а по достижении SHIFT_AUTO_FINISH_HOURS -
# завершаем смену сами (finish_shift_and_notify) и предлагаем указать доход,
# как при обычном ручном завершении (по прямому уточнению пользователя).
SHIFT_AUTO_FINISH_HOURS = 18
SHIFT_AUTO_FINISH_WARN_MINUTES = 30

async def check_long_shifts():
    """Фоновая задача (см. asyncio.create_task в main()) - раз в
    SHIFT_LONG_WARNING_CHECK_MINUTES проверяет всех водителей с активной
    сменой (is_shift_active): шлёт предупреждающий пуш о >12 часов за рулём
    (см. SHIFT_LONG_WARNING_HOURS), предупреждает за
    SHIFT_AUTO_FINISH_WARN_MINUTES до автозавершения на
    SHIFT_AUTO_FINISH_HOURS часах, и автоматически завершает смену, если
    водитель забыл это сделать сам. Оба предупреждения - ОДИН РАЗ за смену
    (флаги в state['shift'], сбрасываются сами собой, т.к. finish_shift
    целиком удаляет state['shift']). Берём срез user_state (list(...)), как
    и другие фоновые рассылки в файле - список не должен "плыть" по ходу
    итерации."""
    while True:
        try:
            await asyncio.sleep(SHIFT_LONG_WARNING_CHECK_MINUTES * 60)
            if not bot:
                continue
            now = datetime.now(timezone.utc)
            for user_id, state in list(user_state.items()):
                if not isinstance(state, dict):
                    continue
                shift = state.get('shift')
                if not shift:
                    continue
                try:
                    started_at = datetime.fromisoformat(shift['started_at'])
                except Exception:
                    continue
                elapsed_hours = (now - started_at).total_seconds() / 3600

                # Автозавершение - проверяем ПЕРВЫМ (если лимит уже
                # достигнут, смена завершается и остальные пуши для неё уже
                # не нужны - state['shift'] исчезнет).
                if elapsed_hours >= SHIFT_AUTO_FINISH_HOURS:
                    category = state.get('category')
                    city = state.get('city')
                    try:
                        await finish_shift_and_notify(
                            user_id, category, city,
                            functools.partial(bot.send_message, user_id),
                            header=(
                                f"⏰ *Смена автоматически завершена после {SHIFT_AUTO_FINISH_HOURS} часов "
                                "секундомера* - мы решили, что ты мог просто забыть её выключить."
                            ),
                        )
                    except Exception as e:
                        logger.error(f"❌ Не удалось автозавершить смену пользователю {user_id}: {e}")
                    continue

                if elapsed_hours >= SHIFT_AUTO_FINISH_HOURS - SHIFT_AUTO_FINISH_WARN_MINUTES / 60 and not shift.get('warned_auto_finish'):
                    try:
                        await bot.send_message(
                            user_id,
                            f"⏰ *Смена скоро завершится автоматически* (через ~{SHIFT_AUTO_FINISH_WARN_MINUTES} мин, "
                            f"по достижении {SHIFT_AUTO_FINISH_HOURS} часов секундомера) - если ты всё ещё за рулём, "
                            "ничего делать не нужно, просто учти это. Завершить сейчас можно кнопкой "
                            "«⏹ ЗАВЕРШИТЬ СМЕНУ» в главном меню.",
                            parse_mode='Markdown',
                        )
                    except Exception as e:
                        logger.error(f"❌ Не удалось отправить пуш о скором автозавершении смены пользователю {user_id}: {e}")
                    shift = dict(state.get('shift') or {})
                    if shift:
                        shift['warned_auto_finish'] = True
                        state['shift'] = shift

                if elapsed_hours < SHIFT_LONG_WARNING_HOURS or shift.get('warned_12h'):
                    continue
                try:
                    await bot.send_message(
                        user_id,
                        f"⚠️ *Ты за рулём уже больше {SHIFT_LONG_WARNING_HOURS} часов подряд!*\n\n"
                        "Долгая смена без отдыха повышает риск аварии - сделай перерыв, "
                        "если получится.\n\n"
                        "Завершить смену можно кнопкой «⏹ ЗАВЕРШИТЬ СМЕНУ» в главном меню.",
                        parse_mode='Markdown',
                    )
                except Exception as e:
                    logger.error(f"❌ Не удалось отправить пуш о долгой смене пользователю {user_id}: {e}")
                # Ставим флаг независимо от успеха отправки - иначе при
                # временной ошибке Telegram будем долбить пуш каждую
                # проверку до конца смены.
                shift = dict(state.get('shift') or {})
                if shift:
                    shift['warned_12h'] = True
                    state['shift'] = shift
        except Exception as e:
            logger.error(f"❌ Ошибка в check_long_shifts: {e}")

def finish_shift(user_id):
    """Останавливает смену, возвращает (duration_minutes, total_km,
    airport_wait_minutes) и сохраняет запись в БД (save_shift_record) -
    вызывается из toggle_shift. Не падает, если смены не было (защитный
    случай - кнопка не должна быть видна в этом состоянии, но на всякий
    случай)."""
    state = user_state[user_id]
    shift = state.pop('shift', None)
    if not shift:
        return 0, 0.0, 0
    started_at = datetime.fromisoformat(shift['started_at'])
    now = datetime.now(timezone.utc)
    duration_minutes = max(0, round((now - started_at).total_seconds() / 60))
    total_km = shift.get('total_km', 0.0)
    airport_wait_minutes = shift.get('airport_wait_minutes', 0)
    # Если смена завершается, пока водитель ещё в радиусе аэропорта
    # (state['airport_queue']['entered_outer_at'] не сброшен) - досчитываем
    # незакрытый интервал простоя, иначе он бы потерялся (см. основной учёт
    # в process_airport_queue_ping при выходе из радиуса).
    aq = state.get('airport_queue') or {}
    if aq.get('entered_outer_at'):
        try:
            entered_at = datetime.fromisoformat(aq['entered_outer_at'])
            airport_wait_minutes += max(0, round((now - entered_at).total_seconds() / 60))
        except Exception:
            pass
    save_shift_record(user_id, started_at, duration_minutes, total_km, airport_wait_minutes)
    # По прямой просьбе пользователя (21.09.2026): "когда завершает смену на
    # карте его не видно" - убираем сразу, не дожидаясь устаревания точки
    # (см. MAP_VISIBILITY_STALE_MINUTES).
    try:
        delete_map_position(user_id)
    except Exception:
        logger.exception(f"❌ Не удалось убрать с карты водителей user_id={user_id} при завершении смены")
    return duration_minutes, total_km, airport_wait_minutes

def format_shift_duration(minutes):
    hours, mins = divmod(minutes, 60)
    if hours and mins:
        return f"{hours} ч {mins} мин"
    if hours:
        return f"{hours} ч"
    return f"{mins} мин"

RU_WEEKDAYS = ('понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота', 'воскресенье')

def format_shift_start_label(started_at):
    """"20:14, суббота" - для сообщения о начале смены (по просьбе
    пользователя, 20.09.2026). started_at - datetime в UTC (как хранится в
    state['shift']['started_at']) - переводим в московское время (UTC+3) для
    показа, т.к. весь бот ориентирован на российских водителей."""
    local = started_at + timedelta(hours=3)
    weekday = RU_WEEKDAYS[local.weekday()]
    return f"{local.strftime('%H:%M')}, {weekday}"

@router.message(lambda message: message.text in ("✅ НАЧАТЬ СМЕНУ", "⏹ ЗАВЕРШИТЬ СМЕНУ"))
async def toggle_shift(message: types.Message):
    """Одна кнопка-переключатель наверху главного меню (выше "💰 КУДА ЕХАТЬ",
    см. services_keyboard) - текст меняется в зависимости от того, идёт ли
    смена, т.к. это одна и та же позиция клавиатуры."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    city = state.get('city')
    if not city:
        await message.answer("Сначала выбери город!")
        return

    if message.text == "✅ НАЧАТЬ СМЕНУ":
        if is_shift_active(state):
            return  # защитный случай - кнопка не должна была показать "Начать", если смена уже идёт
        # По прямой просьбе пользователя (21.09.2026): "когда он нажимает
        # начать смену он автоматически появляется на карте... чтобы в
        # начале смены он указывал в каких тарифах он будет работать и это
        # являлась триггером определении его на карте" - категориям, у
        # которых вообще есть карта (см. MAP_CATEGORY_STYLE), сначала
        # показываем выбор тарифов; остальным (на будущее, если появятся
        # категории без карты) смена стартует сразу без этого шага.
        # Тарифный экран показываем только там, где вообще есть свой список
        # тарифов (shift_tariff_options) - у cargo он пуст, выбирать нечего.
        if category in MAP_CATEGORY_STYLE and shift_tariff_options(category):
            state['shift_tariff_pending'] = set()
            await message.answer(
                "🚕 В каких тарифах работаешь эту смену? Выбери один или несколько, потом нажми «▶️ Начать смену».",
                reply_markup=shift_tariffs_keyboard(category, set()),
            )
            return
        await start_shift_and_notify(message.answer, user_id, category, city, tariffs=[])
        return

    if not is_shift_active(state):
        return  # защитный случай - кнопка не должна была показать "Завершить", если смены нет
    await finish_shift_and_notify(user_id, category, city, message.answer)

class _AnswerFuncAsMessage:
    """Тонкая обёртка вокруг функции-отправителя (message.answer или
    callback_query.message.answer) с сигнатурой message.answer - нужна
    только там, куда функцию уже передали САМУ ПО СЕБЕ (как target в
    start_shift_and_notify), а не объект message целиком, но код дальше
    (send_where_to_go) вызывает именно message.answer(...)."""
    def __init__(self, answer_func):
        self.answer = answer_func

async def start_shift_and_notify(target, user_id, category, city, tariffs):
    """Общая логика старта смены: запускает секундомер/счётчик км
    (start_shift), сразу выводит водителя на карту (update_map_position,
    только для категорий с картой - см. MAP_CATEGORY_STYLE) и шлёт сообщение
    "СМЕНА НАЧАТА" + сводку "Куда ехать". target - message.answer (обычный
    старт) или callback_query.message.answer (после выбора тарифов, см.
    shift_tariff_confirm)."""
    start_shift(user_id, tariffs=tariffs)
    if category in MAP_CATEGORY_STYLE:
        # На карту водитель попадёт с первым же пингом живой геопозиции
        # (см. maybe_update_map_position) - тут только помечаем смену
        # активной с известными тарифами; сама точка появится, как только
        # придёт геопозиция. Если у бота уже есть свежая точка (водитель
        # транслировал геопозицию до старта смены) - публикуем сразу, чтобы
        # не ждать следующего пинга.
        fresh = get_fresh_live_location(user_id)
        if fresh:
            try:
                update_map_position(user_id, city, category, fresh[0], fresh[1], tariffs=tariffs)
            except Exception:
                logger.exception(f"❌ Не удалось сразу вывести на карту user_id={user_id}")
    started_at = datetime.fromisoformat(user_state[user_id]['shift']['started_at'])
    tariffs_line = ""
    if tariffs:
        tariffs_line = f"🚕 Тарифы: {format_shift_tariffs_label(tariffs)}\n"
    shift_header = (
        "🟢 *СМЕНА НАЧАТА*\n"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        f"🕐 {format_shift_start_label(started_at)}\n"
        f"{tariffs_line}"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        "📎 Чтобы считался километраж и ты был виден на карте водителей: Геопозиция → "
        "*«Транслировать геопозицию»* → *«Пока не отключу»*.\n"
        "_Без трансляции секундомер идёт как обычно, но км и показ на карте не сработают._"
    )
    # По просьбе пользователя (20.09.2026): сообщение "СМЕНА НАЧАТА" и
    # сводка "Куда ехать" - теперь ОДНО сообщение (раньше были два
    # отдельных) - см. extra_header у send_where_to_go/
    # format_where_to_go_text. Сначала обновляем клавиатуру коротким
    # тех.сообщением (Reply-клавиатуру нельзя приложить к тому же
    # сообщению, что инлайн-результат "Куда ехать"). Раньше это было
    # только для категорий с аэропортами - теперь доступно всем, включая
    # courier/cargo (у них теперь тоже есть сводка "Куда ехать" на
    # своих часах пика, см. compute_where_to_go).
    await target("✅ Смена начата", reply_markup=services_keyboard(category, city, user_id))
    # send_where_to_go ожидает объект message (зовёт message.answer(...)
    # внутри) - target у нас уже сама функция answer (message.answer или
    # callback_query.message.answer), поэтому оборачиваем в простой объект с
    # атрибутом .answer вместо неё самой (см. _AnswerFuncAsMessage ниже).
    await send_where_to_go(_AnswerFuncAsMessage(target), user_id, city, category, extra_header=shift_header)

@router.callback_query(lambda c: c.data.startswith("shift_tariff_toggle_"))
async def shift_tariff_toggle(callback_query: types.CallbackQuery):
    """Тоггл одного тарифа в клавиатуре выбора перед стартом смены (см.
    shift_tariffs_keyboard) - хранится временно в
    state['shift_tariff_pending'], пока водитель не нажмёт "▶️ Начать
    смену" (shift_tariff_confirm)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    if 'shift_tariff_pending' not in state:
        return  # смена уже стартовала другим путём/клавиатура устарела
    category = state.get('category')
    tariffs = shift_tariff_options(category)
    try:
        idx = int(callback_query.data[len("shift_tariff_toggle_"):])
        label = tariffs[idx]
    except (ValueError, IndexError):
        return
    selected = set(state['shift_tariff_pending'])
    if label in selected:
        selected.discard(label)
    else:
        selected.add(label)
    state['shift_tariff_pending'] = selected
    await callback_query.message.edit_reply_markup(reply_markup=shift_tariffs_keyboard(category, selected))

@router.callback_query(lambda c: c.data == "shift_tariff_confirm")
async def shift_tariff_confirm(callback_query: types.CallbackQuery):
    """Кнопка "▶️ Начать смену" внутри клавиатуры выбора тарифов - можно
    подтвердить и без единого выбранного тарифа (просто не будет подписи
    тарифов на карте, останется только категория)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    if is_shift_active(state):
        return  # защитный случай - двойное нажатие
    tariffs = sorted(state.pop('shift_tariff_pending', set()))
    category = state.get('category')
    city = state.get('city')
    if not city:
        await callback_query.message.answer("Сначала выбери город!")
        return
    await callback_query.message.edit_reply_markup(reply_markup=None)
    await start_shift_and_notify(callback_query.message.answer, user_id, category, city, tariffs)

async def finish_shift_and_notify(user_id, category, city, send_func, header=None):
    """Общая логика завершения смены: считает итоги (finish_shift), шлёт
    сообщение "СМЕНА ЗАВЕРШЕНА" и предлагает указать доход за день - вынесена
    из toggle_shift (по просьбе пользователя, 20.09.2026: "сделай так чтобы
    смена автоматически завершалась после 18 часов"), чтобы тем же кодом
    пользовался и хендлер кнопки "⏹ ЗАВЕРШИТЬ СМЕНУ", и фоновая
    автозавершающая задача (см. check_long_shifts). send_func - функция
    отправки сообщения с сигнатурой message.answer (kwargs reply_markup/
    parse_mode) - у ручного завершения это message.answer, у автоматического
    partial(bot.send_message, user_id). header - опциональный текст ПЕРЕД
    "СМЕНА ЗАВЕРШЕНА" (используется для "⏰ Автоматически завершена по
    достижении лимита времени", см. auto_finish_long_shifts)."""
    duration_minutes, total_km, _airport_wait_minutes = finish_shift(user_id)
    # По просьбе пользователя (21.09.2026): сразу по завершении смены
    # показать потраченное на топливо/эл-заряд, используя ранее сохранённые
    # цену топлива и средний расход (см. FINANCE_REMEMBERED_FIELDS/
    # finance_defaults - тот же профиль, что заполняется в "💰 Финансы"). Если
    # ни разу не вводились - строку пропускаем (не заставляем вводить
    # прямо тут, обычный ввод остаётся в "💰 Указать доход за день" ниже).
    state = user_state.get(user_id) or {}
    defaults = finance_defaults(state)
    consumption = defaults.get('consumption')
    fuel_price = defaults.get('fuel_price')
    fuel_line = ""
    if consumption and fuel_price:
        fuel_cost = (total_km / 100) * consumption * fuel_price
        fuel_line = f"⛽ Потрачено на топливо: ~{fuel_cost:.0f} ₽ ({consumption:g} л/100км × {fuel_price:g} ₽/л)\n"
    body = (
        "🔴 *СМЕНА ЗАВЕРШЕНА*\n"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        f"⏱ {format_shift_duration(duration_minutes)}   🛣 {total_km:.1f} км\n"
        f"{fuel_line}"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        "_Запись сохранена в «💰 Финансы» → «📈 Статистика смен»._"
    )
    if header:
        body = f"{header}\n{body}"
    await send_func(body, reply_markup=services_keyboard(category, city, user_id), parse_mode='Markdown')
    # По просьбе пользователя (20.09.2026): сразу после завершения смены
    # предлагаем указать доход за день - отдельной инлайн-кнопкой (а не
    # сразу форсируем ввод текста, чтобы не мешать, если человек ещё за
    # рулём/занят). Km подставляем автоматически из только что завершённой
    # смены - см. start_finance_after_shift.
    await send_func(
        "Хочешь сразу посчитать доход за эту смену?",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="💰 Указать доход за день", callback_data="start_finance_after_shift"),
        ]]),
    )

def airport_queue_enable_text():
    """Общий текст-инструкция - используется и в toggle_airport_queue_tracking
    (кнопка в Инструментах водителя), и в suggest_airport_queue_tracking (пуш
    сразу после выбора категории, см. select_category) - чтобы не разъезжались
    две копии текста. Рекомендуем «Пока не отключу» (а не «8 часов», как было
    раньше) - при таком выборе трансляция не обрывается сама вообще, водителю
    не нужно ничего вспоминать (если он всё же сам остановит её или она
    прервётся по другой причине - see send_airport_queue_expired_push)."""
    return (
        "📍 *Очередь в аэропорт для Тарифов Яндекс.Go*\n\n"
        "Как включить: скрепка 📎 → Геопозиция → *«Транслировать геопозицию»* → "
        "выбирай *«Пока не отключу»* - трансляция не оборвётся сама, и ты не "
        "пропустишь уведомления. Если сама прервётся (например разрядится "
        "телефон) - напомню включить заново.\n\n"
        "Дальше всё автоматически: пришлю пуш на 2 км от аэропорта, затем на 1 км и 500 м, "
        "и ещё один - через 30 минут, если всё ещё рядом. "
        "Если едешь с заказом, вставать в очередь не планируешь, или геолокация ошиблась "
        "(бывает из-за глушения GPS) - на любом из этих пушей есть кнопка «📍❌ Ошибка GPS / Очередь не требуется», "
        "она отключит напоминания на 30 минут.\n\n"
        "Помогает не терять счёт времени в очереди на получение заказа.\n\n"
        "Чтобы остановить очередь - зайди в «⚙️ Настройки» и нажми «📍 Очередь у аэропорта» ещё раз."
    )

def enable_airport_queue_tracking(user_id):
    state = user_state[user_id]
    state['airport_queue_active'] = True
    state['airport_queue'] = {}

@router.message(lambda message: message.text == "📍 Очередь у аэропорта" and user_state.get(message.from_user.id, {}).get('in_courier_module') and user_state.get(message.from_user.id, {}).get('category') not in CATEGORIES_WITHOUT_AIRPORTS)
async def toggle_airport_queue_tracking(message: types.Message):
    """Кнопка-переключатель (toggle, без отдельного экрана): первое нажатие
    включает отслеживание живой геопозиции и объясняет, как её включить в
    самом Telegram (бот не может запросить живую геопозицию сам - только
    обычный request_location=True, разовую точку, см. handle_nearby_location
    выше - для живой трансляции юзер обязательно жмёт 📎 сам). Повторное
    нажатие выключает и сбрасывает накопленное состояние (см.
    process_airport_queue_ping/check_airport_queue_timers рядом с
    push_airport_status_change). Скрыта для courier/cargo в самой клавиатуре
    (courier_module_keyboard) - фильтр по CATEGORIES_WITHOUT_AIRPORTS в
    декораторе тут просто защита на случай, если кнопка всё же придёт
    текстом (например с уже открытой у пользователя старой клавиатуры)."""
    user_id = message.from_user.id
    state = user_state[user_id]
    category = state.get('category')
    if state.get('airport_queue_active'):
        state['airport_queue_active'] = False
        state['airport_queue'] = {}
        await message.answer("⏹ Отслеживание очереди у аэропорта остановлено.", reply_markup=courier_module_keyboard(category))
        return
    enable_airport_queue_tracking(user_id)
    await message.answer(airport_queue_enable_text(), reply_markup=courier_module_keyboard(category), parse_mode='Markdown')

def airport_queue_bonus_line(user_id, icao, zone_key=None):
    """Необязательная строка-бонус в пуше - последняя САМООТЧЁТНАЯ отметка
    длины очереди от других водителей (см. queue_latest_report/"🚗 Занять
    очередь" - уже существующая, отдельная от геолокации фича). Если свежей
    отметки нет или класс не совпал - просто не добавляем строку, ничего не
    ломается. zone_key - см. _queue_airport_key (чтобы бонус у Шереметьево
    брался именно из очереди своего терминала, а не соседнего)."""
    city = ICAO_TO_CITY.get(icao)
    if not city:
        return ""
    range_str, ts = queue_latest_report(city, icao, queue_class_key(user_id), zone_key=zone_key)
    if not range_str:
        return ""
    local_time = format_airport_local_time(ts, icao)
    return f"\n\n🚗 Последняя отметка водителей: *{range_str}* машин в {local_time}"

def format_airport_queue_push(kind, airport, dist_km, zone_label=None):
    """zone_label - для Шереметьево (см. AIRPORT_TERMINAL_ZONES) уточняет,
    к какому именно терминальному комплексу ближе водитель ("Терминалы B/C"
    или "Терминал D") - у остальных аэропортов всегда None, текст не
    меняется."""
    name = f"{airport['emoji']} {airport['name']}"
    if zone_label:
        # airport['name'] для Шереметьево УЖЕ содержит зону нейтральной
        # записи (ICAO_TO_AIRPORT всегда берёт "SVO (Шереметьево B/C)" - см.
        # комментарий у ICAO_TO_AIRPORT) - без этой обрезки получался бы
        # видимый дубль "(Шереметьево B/C) (Терминалы B/C)" (баг, отчёт
        # пользователя 20.09.2026, скриншот). Срезаем хвост в скобках перед
        # тем как подставить актуальный zone_label.
        base_name = re.sub(r'\s*\([^)]*\)\s*$', '', airport['name'])
        name = f"{airport['emoji']} {base_name} ({zone_label})"
    # ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя, уточнена в тот же
    # день): шкала расстояний теперь 2км/1км/500м (см.
    # AIRPORT_QUEUE_RADIUS_LEVELS_KM) вместо прежних 3км/1.5км - 'enter_outer'
    # остаётся первым (самым дальним) уровнем ради обратной совместимости
    # имени, остальные - 'enter_level_N' по индексу в AIRPORT_QUEUE_RADIUS_LEVELS_KM.
    if kind == 'enter_outer':
        return f"📍 Вы примерно в {dist_km:.1f} км от {name}.\n\nОтслеживаю время рядом - напомню по мере приближения, а дальше через 30 минут, если всё ещё будете рядом."
    if isinstance(kind, str) and kind.startswith('enter_level_'):
        if dist_km < 1:
            dist_label = f"{round(dist_km * 1000)} м"
        else:
            dist_label = f"{dist_km:.1f} км"
        return f"📍 Вы уже в {dist_label} от {name} - почти на месте."
    if kind == 30:
        return f"⏱ Вы уже 30 минут рядом с {name}."
    return ""

def find_airport_queue_join_target(icao, zone_key=None):
    """Находит (city, airport_idx) в AIRPORTS_INFO для кнопки "🚗 Встать в
    очередь" на гео-пуше об аэропорте - переиспользует ту же самоотчётную
    очередь (callback_data f"join_queue_{city}_{idx}"), что и кнопка
    "🚗 Занять очередь" в разделе "✈️🚆 Авиа/ЖД" (см. show_range_picker). По
    прямой просьбе пользователя (20.09.2026): "каждый пуш от аэропорта
    должен предлагать чтобы водитель не забывал вставать в очередь". Для
    аэропортов с зонами (Шереметьево) ищет запись именно с нужным zone_key,
    чтобы отметка ушла в правильную зону (B/C или D), а не в первую
    попавшуюся; без совпадения по зоне - берёт первую запись с этим icao."""
    city = ICAO_TO_CITY.get(icao)
    if not city:
        return None
    airports = AIRPORTS_INFO.get(city, [])
    if zone_key:
        for i, airport in enumerate(airports):
            if airport.get('icao') == icao and airport.get('zone_key') == zone_key:
                return (city, i)
    for i, airport in enumerate(airports):
        if airport.get('icao') == icao:
            return (city, i)
    return None


async def send_airport_queue_push(user_id, icao, kind, dist_km=None, zone_label=None, zone_key=None):
    if not bot:
        return
    airport = ICAO_TO_AIRPORT.get(icao)
    if not airport:
        return
    text = format_airport_queue_push(kind, airport, dist_km if dist_km is not None else 0, zone_label)
    text += airport_queue_bonus_line(user_id, icao, zone_key)
    reply_markup = None
    target = find_airport_queue_join_target(icao, zone_key)
    if target:
        target_city, airport_idx = target
        buttons = []
        # ДОБАВЛЕНО 20.09.2026 (по просьбе пользователя - "если он отметился
        # в зоне аэропорта раз, второй раз можно уже не спрашивать"): если у
        # водителя уже есть СВОЯ свежая отметка по этому аэропорту/терминалу
        # (он уже проходил выбор тарифа и диапазона недавно) - добавляем
        # кнопку-подтверждение "✅ Уже в очереди", которая одним нажатием
        # просто освежает время той же самой отметки (тот же диапазон машин),
        # без повторного выбора тарифа/диапазона. "🚗 Встать в очередь"
        # остаётся рядом - на случай, если число машин в очереди изменилось
        # и нужно отметить заново.
        own_marks = user_recent_queue_marks(user_id, target_city, icao, zone_key)
        if own_marks:
            keep_key = f"qkeep_{target_city}_{icao}_{zone_key or '-'}"
            buttons.append([InlineKeyboardButton(text="✅ Уже в очереди", callback_data=keep_key)])
        buttons.append([InlineKeyboardButton(text="🚗 Встать в очередь" if not own_marks else "🔄 Обновить очередь", callback_data=f"join_queue_{target_city}_{airport_idx}")])
        # ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя): водитель может
        # ехать с заказом/без намерения вставать в очередь этого аэропорта -
        # кнопка снимает пуши очереди на AIRPORT_QUEUE_SNOOZE_MINUTES минут
        # для ЭТОГО аэропорта/зоны, "чтобы человека лишний раз не тревожить".
        # На ВСЕХ пушах очереди (по прямой просьбе пользователя), не только
        # на первом.
        buttons.append([InlineKeyboardButton(text="📍❌ Ошибка GPS / Очередь не требуется", callback_data=f"aqsnooze_{icao}_{zone_key or '-'}")])
        reply_markup = InlineKeyboardMarkup(inline_keyboard=buttons)
    try:
        await bot.send_message(user_id, text, reply_markup=reply_markup, parse_mode='Markdown')
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш об очереди у аэропорта пользователю {user_id}: {e}")

async def send_airport_queue_expired_push(user_id, icao):
    """Пуш-напоминание на случай, когда трансляция геопозиции, судя по
    всему, закончилась (см. check_airport_queue_timers) - по просьбе
    пользователя, чтобы водитель не забывал включить её заново, если он
    всё ещё работает. icao может быть None (трансляция началась, но юзер
    ни разу не оказывался рядом ни с одним аэропортом) - тогда просто без
    упоминания конкретного аэропорта."""
    if not bot:
        return
    airport = ICAO_TO_AIRPORT.get(icao) if icao else None
    where = f" у {airport['emoji']} {airport['name']}" if airport else ""
    text = (
        f"📡 Трансляция геопозиции{where}, похоже, закончилась.\n\n"
        f"Если ты всё ещё на линии - включи её заново: скрепка 📎 → Геопозиция → "
        f"«Транслировать геопозицию» → *«Пока не отключу»*, чтобы не пропускать отметки "
        f"об очереди у аэропорта."
    )
    try:
        await bot.send_message(user_id, text, parse_mode='Markdown')
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш об окончании трансляции геопозиции пользователю {user_id}: {e}")

async def process_airport_queue_ping(user_id, lat, lon, live_period=None):
    """Обрабатывает один пинг геопозиции (и разовый message.location, и
    последующие edited_message.location трансляции - см. хендлеры ниже) -
    считает расстояние до ближайшего аэропорта (и, для Шереметьево, до
    ближайшей терминальной зоны - см. nearest_airport_zone/
    AIRPORT_TERMINAL_ZONES), шлёт пуши по мере приближения (см.
    AIRPORT_QUEUE_RADIUS_LEVELS_KM), обновляет user_state[uid]['airport_queue']
    для фонового чекера (30 мин - см. check_airport_queue_timers)."""
    state = user_state.get(user_id)
    if not state or not state.get('airport_queue_active'):
        return
    if state.get('category') in CATEGORIES_WITHOUT_AIRPORTS:
        # Защитный случай - активная трансляция, начатая ДО смены категории
        # на courier/cargo, не должна продолжать слать аэропортовые пуши.
        return
    icao, dist_km, zone_key, zone_label = nearest_airport_zone(lat, lon)
    if icao is None:
        return
    now = datetime.now(ZoneInfo('UTC'))
    aq = dict(state.get('airport_queue') or {})
    # ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя - кнопка "не буду
    # вставать в очередь" на пуше, "чтобы человека лишний раз не тревожить"):
    # если водитель нажал эту кнопку для ТЕКУЩЕГО аэропорта/зоны недавно
    # (см. AIRPORT_QUEUE_SNOOZE_MINUTES/handle_airport_queue_snooze) - не
    # шлём никаких пушей вообще, пока snooze не истёк. Координаты/время
    # последнего пинга (aq['last_update_at']) всё равно обновляются ниже -
    # snooze не должен путать check_airport_queue_timers's "трансляция
    # прервалась" со снятой отметкой "не хочу пушей".
    snoozed_until_str = aq.get('snoozed_until')
    is_snoozed = False
    if snoozed_until_str and (aq.get('icao'), aq.get('zone_key')) == (icao, zone_key):
        try:
            is_snoozed = now < datetime.fromisoformat(snoozed_until_str)
        except Exception:
            is_snoozed = False
    # Смена АЭРОПОРТА или, для Шереметьево, смена ЗОНЫ (B <-> C <-> D,
    # это отдельные подъезды - водитель, переехавший из одной в другую,
    # по факту заново въезжает в радиус) - начинаем отслеживание с чистого
    # листа. У однозонных аэропортов zone_key всегда None, so сравнение
    # (icao, zone_key) для них эквивалентно старому сравнению icao.
    if (aq.get('icao'), aq.get('zone_key')) != (icao, zone_key):
        aq = {'icao': icao, 'zone_key': zone_key}
        # Аэропорт/зона сменились - is_snoozed уже вычислен выше ДО этого
        # сброса и относился к СТАРОЙ паре (icao, zone_key), поэтому здесь
        # больше не действует (новый заход = новый снуз с нуля, если
        # понадобится). Явно гасим, чтобы не унести устаревшее значение.
        is_snoozed = False
    aq['last_update_at'] = now.isoformat()
    if live_period:
        aq['live_period'] = live_period
    if snoozed_until_str:
        aq['snoozed_until'] = snoozed_until_str  # переносим snooze дальше, пока не истёк (см. is_snoozed выше)

    if dist_km <= AIRPORT_QUEUE_RADIUS_LEVELS_KM[0]:
        if not aq.get('entered_outer_at'):
            # Первый вход в САМЫЙ ШИРОКИЙ радиус - как и раньше, начало
            # отсчёта для таймера "уже 30 минут рядом" (см. check_airport_queue_timers).
            aq['entered_outer_at'] = now.isoformat()
            aq['pushed_30'] = False
        # ИЗМЕНЕНО 21.09.2026: раньше было только 2 фиксированных уровня
        # (outer/inner), теперь идём по AIRPORT_QUEUE_RADIUS_LEVELS_KM (3
        # км/2км/1км/500м) по порядку - шлём пуш за каждый уровень, который
        # водитель проходит ВПЕРВЫЕ за этот заход (entered_levels - список
        # уже пройденных индексов уровня, чтобы не дублировать пуш при
        # повторных пингах на том же расстоянии). Если сейчас snooze
        # (водитель нажал "не буду вставать в очередь") - уровень всё равно
        # ЗАПОМИНАЕМ как пройденный (чтобы после истечения snooze не
        # засыпало пушами за все пропущенные уровни разом), но пуш НЕ шлём.
        entered_levels = set(aq.get('entered_levels') or [])
        for level_idx, level_km in enumerate(AIRPORT_QUEUE_RADIUS_LEVELS_KM):
            if dist_km <= level_km and level_idx not in entered_levels:
                entered_levels.add(level_idx)
                if not is_snoozed:
                    kind = 'enter_outer' if level_idx == 0 else f'enter_level_{level_idx}'
                    await send_airport_queue_push(user_id, icao, kind, dist_km, zone_label, zone_key)
        aq['entered_levels'] = sorted(entered_levels)
    else:
        # Вышел за пределы внешнего радиуса - сбрасываем: при возвращении
        # отсчёт (и пуши на вход/по времени) начнётся заново.
        if aq.get('entered_outer_at'):
            # По просьбе пользователя (20.09.2026): если сейчас идёт смена -
            # копим суммарное время простоя в аэропорту за смену
            # (state['shift']['airport_wait_minutes']), чтобы учесть его в
            # итоговом расчёте финансов (см. send_courier_finance_result).
            shift = state.get('shift')
            if shift:
                try:
                    entered_at = datetime.fromisoformat(aq['entered_outer_at'])
                    wait_minutes = max(0, round((now - entered_at).total_seconds() / 60))
                except Exception:
                    wait_minutes = 0
                shift = dict(shift)
                shift['airport_wait_minutes'] = shift.get('airport_wait_minutes', 0) + wait_minutes
                state['shift'] = shift
            aq = {'icao': icao, 'zone_key': zone_key, 'last_update_at': now.isoformat()}
            if live_period:
                aq['live_period'] = live_period

    state['airport_queue'] = aq

def _location_tracking_active(user_id):
    """True, если хоть одна из фич, использующих живую геопозицию (очередь у
    аэропорта, счётчик км текущей смены), сейчас активна у этого
    пользователя - обе читают ОДНУ и ту же трансляцию (Telegram позволяет
    транслировать только одну геопозицию за раз), см. комментарий у
    handle_airport_queue_location."""
    state = user_state.get(user_id, {})
    return bool(state.get('airport_queue_active') or is_shift_active(state))

# Сколько минут последняя точка живой трансляции считается ещё актуальной
# для разовых запросов (Мойки/Шиномонтаж/Туалеты/Парковка и т.п., см.
# show_nearby_prompt) и для подсказки "включить трансляцию" после выбора
# категории (см. select_category) - если водитель уже транслирует геопозицию
# (см. _location_tracking_active), не спрашиваем её заново, а берём
# последнюю известную точку (по жалобе пользователя, 20.09.2026: "локация
# горит уже а бот опять предлагает"). Если пинга давно не было (например,
# трансляция зависла) - точка считается устаревшей, и бот всё-таки спросит
# заново.
#
# БЫЛО 10 минут - недостаточно: Telegram не гарантирует частые edited_message
# с обновлением координат, если водитель физически стоит на месте (машина
# на стоянке, ждёт заказ и т.п.) - трансляция при этом продолжает идти, но
# новых пингов может не быть заметно дольше 10 минут, и бот снова "терял"
# то, что трансляция активна (повторная жалоба пользователя, 21.09.2026, со
# скриншотом: "сверху у нас включена трансляция локации а он опять это
# запрашивает"). Подняли до того же порога, что уже используется для
# определения "трансляция реально прервалась" у очереди аэропорта (см.
# AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES выше) - ниже этого порога транслицию
# нигде в файле не считаем остановившейся, так что логично не считать её
# остановившейся и здесь.
LIVE_LOCATION_FRESH_MINUTES = AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES

def remember_live_location(user_id, lat, lon):
    state = user_state.get(user_id)
    if state is None:
        return
    state['last_live_location'] = {
        'lat': lat, 'lon': lon,
        'updated_at': datetime.now(timezone.utc).isoformat(),
    }

def get_fresh_live_location(user_id):
    """Возвращает (lat, lon) последней живой геопозиции, если она не старше
    LIVE_LOCATION_FRESH_MINUTES - иначе None (пусть бот спросит как обычно).
    Не требует, чтобы _location_tracking_active была True - трансляция могла
    быть включена водителем самостоятельно, без кнопок бота (см.
    handle_passive_live_location), и last_live_location всё равно свежая."""
    state = user_state.get(user_id) or {}
    loc = state.get('last_live_location')
    if not loc:
        return None
    try:
        updated_at = datetime.fromisoformat(loc['updated_at'])
    except Exception:
        return None
    age_minutes = (datetime.now(timezone.utc) - updated_at).total_seconds() / 60
    if age_minutes > LIVE_LOCATION_FRESH_MINUTES:
        return None
    return loc['lat'], loc['lon']

# ==================== КАРТА ВОДИТЕЛЕЙ ====================
# По прямой просьбе пользователя (21.09.2026): "карта водителей все те кто
# есть в этом боте чтобы они нажимали и все видели друг друга чтобы таксисты
# были помечены как таксисты допустим жёлтым символом... Ультима... чёрный
# курьеры... белым грузовые красным". Реализовано как настоящая интерактивная
# Telegram WebApp-карта (Leaflet.js + OpenStreetMap, без ключей API) - НЕ
# статичная картинка. Показ на карте - ОТДЕЛЬНОЕ явное согласие
# ("🗺 Показываться на карте" в Настройках), отдельное от остальных фич на
# живой геопозиции (счётчик км смены, очередь у аэропорта) - включение той
# трансляции НЕ включает автоматически показ на карте, по прямому уточнению
# пользователя при обсуждении фичи. На карте виден только тариф/категория
# (цветной маркер + подпись), БЕЗ имени и БЕЗ user_id - см. get_map_positions.

# Сколько минут последняя известная точка водителя ещё показывается на общей
# карте - после этого маркер считается устаревшим и не отдаётся API
# /map/positions (водитель мог закрыть бота/остановить трансляцию).
MAP_VISIBILITY_STALE_MINUTES = 15

# Цвет и подпись маркера на карте по категории - см. просьбу пользователя
# выше (такси-жёлтый/Ultima-чёрный/курьер-белый/грузовой-красный).
MAP_CATEGORY_STYLE = {
    'taxi': {'color': '#FFD400', 'label': 'Такси'},
    'ultima': {'color': '#111111', 'label': 'Ultima'},
    'courier': {'color': '#FFFFFF', 'label': 'Курьер'},
    'cargo': {'color': '#E53935', 'label': 'Грузовое такси'},
}

MAP_WEBAPP_PATH = '/map'
MAP_POSITIONS_API_PATH = '/map/positions'
MAP_AIRPORTS_API_PATH = '/map/airports'

# Категории, чья очередь показывается в попапе аэропорта на карте (по
# просьбе пользователя, 22.09.2026: "названия и очереди какие сейчас там
# плюс текущая загрузка... открыт он или закрыт") - курьер/грузовое такси
# у аэропортов не отмечаются (см. CATEGORIES_WITHOUT_AIRPORTS), поэтому
# для них очередь не считаем.
MAP_AIRPORT_QUEUE_CATEGORIES = ['taxi', 'ultima']

def update_map_position(user_id, city, category, lat, lon, tariffs=None):
    """Записывает/обновляет последнюю позицию водителя для общей карты.
    Вызывается только пока у водителя активна смена (см.
    maybe_update_map_position/start_shift_and_notify) - сюда напрямую лучше
    не звать. tariffs - список тарифов, выбранных при старте смены (см.
    shift_tariffs_keyboard), для подписи маркера."""
    conn = get_db_connection()
    cursor = conn.cursor()
    tariffs_json = json.dumps(list(tariffs or []), ensure_ascii=False)
    cursor.execute('''
        INSERT INTO map_positions (user_id, city, category, lat, lon, tariffs, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(user_id) DO UPDATE SET
            city = excluded.city, category = excluded.category,
            lat = excluded.lat, lon = excluded.lon, tariffs = excluded.tariffs,
            updated_at = CURRENT_TIMESTAMP
    ''', (user_id, city, category, lat, lon, tariffs_json))
    conn.commit()
    conn.close()

def delete_map_position(user_id):
    """Убирает водителя с карты - при завершении смены (см. finish_shift) или
    если пропала живая геопозиция дольше MAP_VISIBILITY_STALE_MINUTES (тогда
    точка и так больше не отдаётся get_map_positions, это просто явная
    уборка, чтобы не копить старые строки)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('DELETE FROM map_positions WHERE user_id = ?', (user_id,))
    conn.commit()
    conn.close()

def get_map_positions(city, category=None):
    """Отдаёт список позиций для карты конкретного города - только
    категория/тарифы/координаты, БЕЗ user_id и имени (приватность, по
    просьбе пользователя - подпись маркера только "какой тариф").
    Отфильтровывает устаревшие точки (см. MAP_VISIBILITY_STALE_MINUTES). По
    просьбе пользователя (21.09.2026): по умолчанию карта показывает ТОЛЬКО
    свою категорию (такси видит такси, Ultima - только Ultima и т.д.) -
    параметр category, если задан, фильтрует запрос; category=None (или
    "all") - вся карта целиком (переключатель "Показать все" внутри WebApp,
    см. map_webapp_html)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    if category and category in MAP_CATEGORY_STYLE:
        cursor.execute('''
            SELECT category, lat, lon, tariffs FROM map_positions
            WHERE city = ? AND category = ? AND updated_at >= datetime('now', ?)
        ''', (city, category, f'-{MAP_VISIBILITY_STALE_MINUTES} minutes'))
    else:
        cursor.execute('''
            SELECT category, lat, lon, tariffs FROM map_positions
            WHERE city = ? AND updated_at >= datetime('now', ?)
        ''', (city, f'-{MAP_VISIBILITY_STALE_MINUTES} minutes'))
    rows = cursor.fetchall()
    conn.close()
    result = []
    for r in rows:
        try:
            tariffs = json.loads(r[3]) if r[3] else []
        except Exception:
            tariffs = []
        result.append({'category': r[0], 'lat': r[1], 'lon': r[2], 'tariffs': tariffs})
    return result

def get_all_map_positions_with_user_id():
    """Как get_map_positions, но ВКЛЮЧАЕТ user_id и без фильтра по городу -
    только для служебного использования внутри бота (см.
    check_nearby_drivers ниже), НИКОГДА не отдаётся во внешний JSON API
    (там всегда get_map_positions без user_id, ради приватности)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT user_id, city, category, lat, lon, tariffs FROM map_positions
        WHERE updated_at >= datetime('now', ?)
    ''', (f'-{MAP_VISIBILITY_STALE_MINUTES} minutes',))
    rows = cursor.fetchall()
    conn.close()
    result = []
    for r in rows:
        try:
            tariffs = json.loads(r[5]) if r[5] else []
        except Exception:
            tariffs = []
        result.append({'user_id': r[0], 'city': r[1], 'category': r[2], 'lat': r[3], 'lon': r[4], 'tariffs': tariffs})
    return result

# ==================== ПУШ "РЯДОМ ЕСТЬ ВОДИТЕЛЬ" ====================
# По прямой просьбе пользователя (21.09.2026): "если водителя находятся друг
# с дружкой рядом на расстоянии меньше 300 м и находятся больше [5 минут] в
# таком состоянии чтоб присылал Push что с вами есть рядом водитель такой-то
# категории... если курьер то курьер если Ультима то Ультима... только
# премьер премьера элит элита" - пара водителей должна быть ОДНОЙ категории
# (такси видит только такси и т.д., как и вся карта - см. MAP_CATEGORY_STYLE)
# и, если у обоих указаны тарифы при старте смены (см. shift_tariffs_keyboard),
# у них должен быть хотя бы один ОБЩИЙ тариф (Премьер видит Премьера, Эконом -
# Эконома, а не любого таксиста без разбора). Пуш шлётся ОДИН РАЗ на пару, пока
# они не разъедутся дальше NEARBY_DRIVERS_RADIUS_KM - потом, если снова
# окажутся рядом, отсчёт и пуш начинаются заново (по прямому уточнению
# пользователя - "один раз", а не периодически).
NEARBY_DRIVERS_RADIUS_KM = 0.3
NEARBY_DRIVERS_MINUTES = 5
NEARBY_DRIVERS_CHECK_INTERVAL_MINUTES = 1

# In-memory (не в БД - это лёгкий эфемерный трекер, переживать перезапуск
# бота ему не нужно: после рестарта пары просто отсчитаются заново).
# Ключ - frozenset({user_id_1, user_id_2}).
_nearby_pairs_since = {}   # ключ -> datetime, когда пара впервые оказалась рядом
_nearby_pairs_notified = set()  # ключи пар, которым уже отправлен пуш (пока не разъедутся)

def _tariffs_overlap_or_unset(tariffs_a, tariffs_b):
    """True, если у пары есть общий тариф, либо тарифы не указаны хотя бы у
    одного из них (тогда сверяем только по категории - см. вызов ниже)."""
    if not tariffs_a or not tariffs_b:
        return True
    return bool(set(tariffs_a) & set(tariffs_b))

async def check_nearby_drivers():
    """Раз в NEARBY_DRIVERS_CHECK_INTERVAL_MINUTES проверяет все активные
    позиции на карте (см. get_all_map_positions_with_user_id), находит пары
    водителей одной категории (и с пересекающимися тарифами, если тарифы
    указаны у обоих) ближе NEARBY_DRIVERS_RADIUS_KM друг к другу, и если они
    остаются рядом дольше NEARBY_DRIVERS_MINUTES - шлёт пуш обоим (один раз,
    пока не разъедутся). O(n²) по водителям внутри одного города и категории -
    при реалистичных масштабах (десятки-сотни одновременно активных смен на
    город) это тривиально дёшево, специальная пространственная индексация не
    нужна."""
    if not bot:
        return
    positions = get_all_map_positions_with_user_id()
    # Группируем по (город, категория) - пары имеют смысл только внутри
    # одного города и одной категории (см. комментарий к блоку выше).
    groups = {}
    for p in positions:
        key = (p['city'], p['category'])
        groups.setdefault(key, []).append(p)

    now = datetime.now(timezone.utc)
    currently_close = set()

    for (_city, _category), drivers in groups.items():
        for i in range(len(drivers)):
            for j in range(i + 1, len(drivers)):
                a, b = drivers[i], drivers[j]
                if a['user_id'] == b['user_id']:
                    continue
                if not _tariffs_overlap_or_unset(a['tariffs'], b['tariffs']):
                    continue
                dist_km = haversine_km(a['lat'], a['lon'], b['lat'], b['lon'])
                if dist_km > NEARBY_DRIVERS_RADIUS_KM:
                    continue
                pair_key = frozenset((a['user_id'], b['user_id']))
                currently_close.add(pair_key)
                since = _nearby_pairs_since.get(pair_key)
                if since is None:
                    _nearby_pairs_since[pair_key] = now
                    continue
                elapsed_minutes = (now - since).total_seconds() / 60
                if elapsed_minutes < NEARBY_DRIVERS_MINUTES or pair_key in _nearby_pairs_notified:
                    continue
                _nearby_pairs_notified.add(pair_key)
                await _send_nearby_driver_pushes(a, b)

    # Пары, которые больше не рядом (разъехались дальше радиуса, или один из
    # водителей завершил смену/пропал с карты) - сбрасываем таймер и флаг
    # "уже уведомлены", чтобы при новой встрече отсчёт начался заново.
    stale_keys = [k for k in _nearby_pairs_since if k not in currently_close]
    for k in stale_keys:
        _nearby_pairs_since.pop(k, None)
        _nearby_pairs_notified.discard(k)

def _nearby_driver_label(driver):
    """"Премьер, Комфорт" или просто название категории (Такси/Ultima/...),
    если тарифы не указаны - для текста пуша (см. _send_nearby_driver_pushes)."""
    if driver['tariffs']:
        return format_shift_tariffs_label(driver['tariffs'])
    return MAP_CATEGORY_STYLE.get(driver['category'], {}).get('label', driver['category'])

async def _send_nearby_driver_pushes(a, b):
    """Шлёт обоим водителям пары пуш о том, что рядом коллега - каждому про
    категорию/тариф ДРУГОГО (без user_id/имени - та же приватность, что и на
    самой карте, см. get_map_positions)."""
    dist_m = round(haversine_km(a['lat'], a['lon'], b['lat'], b['lon']) * 1000)
    for me, other in ((a, b), (b, a)):
        label = _nearby_driver_label(other)
        text = (
            f"📍 Рядом с тобой (~{dist_m} м) уже больше {NEARBY_DRIVERS_MINUTES} минут "
            f"есть ещё один водитель: *{label}*."
        )
        try:
            await bot.send_message(me['user_id'], text, parse_mode='Markdown')
        except Exception:
            logger.warning(f"⚠️ Не удалось отправить пуш о соседнем водителе user_id={me['user_id']}")
        await asyncio.sleep(0.05)

async def nearby_drivers_checker():
    while True:
        try:
            await check_nearby_drivers()
        except Exception:
            logger.exception("❌ Ошибка фоновой проверки соседних водителей")
        await asyncio.sleep(NEARBY_DRIVERS_CHECK_INTERVAL_MINUTES * 60)

def maybe_update_map_position(user_id, lat, lon):
    """Хук из обработчиков живой геопозиции (см. вызовы ниже) - пишет позицию
    в map_positions, ТОЛЬКО пока у водителя идёт смена (см.
    is_shift_active/start_shift_and_notify) - по прямому уточнению
    пользователя (21.09.2026): "когда он нажимает начать смену он
    автоматически появляется на карте когда завершает смену на карте его не
    видно". Отдельной настройки-тумблера для показа на карте больше нет.
    Если категория не входит в MAP_CATEGORY_STYLE (на всякий случай) -
    ничего не пишет."""
    state = user_state.get(user_id) or {}
    shift = state.get('shift')
    if not shift:
        return
    category = state.get('category')
    city = state.get('city')
    if not category or not city or category not in MAP_CATEGORY_STYLE:
        return
    try:
        update_map_position(user_id, city, category, lat, lon, tariffs=shift.get('tariffs'))
    except Exception:
        logger.exception(f"❌ Не удалось обновить позицию на карте для user_id={user_id}")

def validate_telegram_webapp_init_data(init_data, bot_token):
    """Проверка подписи initData от Telegram WebApp - официальный алгоритм
    (https://core.telegram.org/bots/webapps#validating-data-received-via-the-web-app):
    secret_key = HMAC-SHA256(bot_token, key="WebAppData"), затем
    hash сравнивается с HMAC-SHA256(data_check_string, key=secret_key), где
    data_check_string - все поля кроме hash, отсортированные по ключу и
    склеенные через '\\n' как "key=value". Возвращает распарсенные поля (dict)
    при успехе, иначе None."""
    try:
        parsed = dict(urllib.parse.parse_qsl(init_data, strict_parsing=True))
    except Exception:
        return None
    received_hash = parsed.pop('hash', None)
    if not received_hash:
        return None
    data_check_string = '\n'.join(f'{k}={v}' for k, v in sorted(parsed.items()))
    secret_key = hmac.new(b'WebAppData', bot_token.encode(), hashlib.sha256).digest()
    computed_hash = hmac.new(secret_key, data_check_string.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(computed_hash, received_hash):
        return None
    return parsed

def map_webapp_html():
    """HTML-страница WebApp с интерактивной картой (Leaflet.js + OpenStreetMap
    тайлы, без API-ключей). Город и категория самого водителя берутся из
    query-параметров ?city=&category=, которые подставляются в URL кнопки при
    создании клавиатуры (см. services_keyboard). По просьбе пользователя
    (21.09.2026): по умолчанию карта показывает ТОЛЬКО свою категорию (такси -
    только такси, Ultima - только Ultima, курьер - только курьеров, грузовое
    такси - только грузовые), с переключателем "Показать все" внутри самой
    карты, чтобы посмотреть остальные категории тоже. Запрашивает
    /map/positions?city=&category= с заголовком, содержащим initData, для
    проверки подписи на сервере (см. validate_telegram_webapp_init_data)."""
    style_json = json.dumps(MAP_CATEGORY_STYLE, ensure_ascii=False)
    return f"""<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Карта водителей</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css">
<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script>
<style>
  html, body, #map {{ height: 100%; margin: 0; padding: 0; }}
  .legend {{ position: absolute; top: 10px; right: 10px; z-index: 1000; background: #fff; border-radius: 8px; padding: 8px 10px; font-family: -apple-system, sans-serif; font-size: 12px; box-shadow: 0 1px 4px rgba(0,0,0,.25); }}
  .legend div {{ display: flex; align-items: center; gap: 6px; margin: 3px 0; }}
  .legend .dot {{ width: 11px; height: 11px; border-radius: 50%; border: 1px solid #999; display: inline-block; }}
  .filter-toggle {{ position: absolute; top: 10px; left: 10px; z-index: 1000; background: #fff; border-radius: 8px; padding: 8px 12px; font-family: -apple-system, sans-serif; font-size: 12.5px; font-weight: 600; box-shadow: 0 1px 4px rgba(0,0,0,.25); cursor: pointer; user-select: none; }}
  .airport-icon {{ display: flex; align-items: center; justify-content: center; font-size: 20px; filter: drop-shadow(0 1px 2px rgba(0,0,0,.5)); }}
  .airport-popup h4 {{ margin: 0 0 4px; font-family: -apple-system, sans-serif; font-size: 13.5px; }}
  .airport-popup .row {{ font-family: -apple-system, sans-serif; font-size: 12.5px; margin: 2px 0; }}
  .airport-label {{ background: rgba(255,255,255,.95); border: 1px solid rgba(0,0,0,.15); border-radius: 6px; padding: 3px 6px; font-family: -apple-system, sans-serif; font-size: 11px; line-height: 1.35; white-space: nowrap; box-shadow: 0 1px 3px rgba(0,0,0,.25); }}
  .airport-label b {{ font-size: 11.5px; }}
  .road-icon {{ display: flex; align-items: center; justify-content: center; font-size: 16px; filter: drop-shadow(0 1px 2px rgba(0,0,0,.5)); }}
  .road-popup {{ font-family: -apple-system, sans-serif; font-size: 12.5px; max-width: 220px; }}
  .road-popup .time {{ color: #777; font-size: 11px; margin-top: 4px; }}
  .road-popup a {{ color: #1a73e8; }}
  .event-icon {{ display: flex; align-items: center; justify-content: center; font-size: 16px; filter: drop-shadow(0 1px 2px rgba(0,0,0,.5)); }}
  .event-popup {{ font-family: -apple-system, sans-serif; font-size: 12.5px; max-width: 220px; }}
  .event-popup h4 {{ margin: 0 0 4px; font-size: 13px; }}
  .event-popup .place {{ color: #555; }}
  .event-popup .time {{ color: #777; font-size: 11px; margin-top: 4px; }}
  .event-popup a {{ color: #1a73e8; }}
</style>
</head>
<body>
<div id="map"></div>
<div class="filter-toggle" id="filterToggle">Показать все категории</div>
<div class="legend" id="legend"></div>
<script>
  const CATEGORY_STYLE = {style_json};
  const CATEGORY_LABEL = {{ taxi: 'Такси', ultima: 'Ultima' }};
  const STATUS_ICON = {{ open: '🟢', coordinated: '🟡', closed: '🔴' }};
  const tg = window.Telegram && window.Telegram.WebApp;
  if (tg) {{ tg.ready(); tg.expand(); }}
  const params = new URLSearchParams(window.location.search);
  const city = params.get('city') || '';
  const myCategory = params.get('category') || '';
  let showAll = !myCategory;
  const legend = document.getElementById('legend');
  const toggle = document.getElementById('filterToggle');
  function renderLegend() {{
    legend.innerHTML = '';
    const keys = showAll ? Object.keys(CATEGORY_STYLE) : [myCategory];
    keys.forEach(key => {{
      const s = CATEGORY_STYLE[key];
      if (!s) return;
      legend.innerHTML += `<div><span class="dot" style="background:${{s.color}}"></span>${{s.label}}</div>`;
    }});
  }}
  function renderToggle() {{
    if (!myCategory) {{ toggle.style.display = 'none'; return; }}
    toggle.textContent = showAll ? 'Только моя категория' : 'Показать все категории';
  }}
  toggle.addEventListener('click', () => {{
    showAll = !showAll;
    renderLegend();
    renderToggle();
    loadPositions();
  }});
  renderLegend();
  renderToggle();
  const map = L.map('map').setView([55.7558, 37.6173], 11);
  L.tileLayer('https://{{s}}.tile.openstreetmap.org/{{z}}/{{x}}/{{y}}.png', {{
    attribution: '© OpenStreetMap',
    maxZoom: 19,
  }}).addTo(map);
  let markers = [];
  let airportMarkers = [];
  let airportsLoaded = false;
  async function loadPositions() {{
    try {{
      const initData = tg ? tg.initData : '';
      const categoryParam = showAll ? '' : myCategory;
      const resp = await fetch(`/map/positions?city=${{encodeURIComponent(city)}}&category=${{encodeURIComponent(categoryParam)}}`, {{
        headers: {{ 'X-Telegram-Init-Data': initData }},
      }});
      if (!resp.ok) return;
      const data = await resp.json();
      markers.forEach(m => map.removeLayer(m));
      markers = [];
      let bounds = [];
      data.positions.forEach(p => {{
        const style = CATEGORY_STYLE[p.category] || {{ color: '#888', label: p.category }};
        const popupText = (p.tariffs && p.tariffs.length) ? `${{style.label}} (${{p.tariffs.join(', ')}})` : style.label;
        const marker = L.circleMarker([p.lat, p.lon], {{
          radius: 9, color: '#333', weight: 1.5, fillColor: style.color, fillOpacity: 0.9,
        }}).bindPopup(popupText).addTo(map);
        markers.push(marker);
        bounds.push([p.lat, p.lon]);
      }});
      if (bounds.length && !airportsLoaded) map.fitBounds(bounds, {{ padding: [30, 30], maxZoom: 13 }});
    }} catch (e) {{ /* тихо - карта просто останется пустой до следующего опроса */ }}
  }}
  // Метки аэропортов - название, статус (открыт/по согласованию/закрыт),
  // текущая загрузка % и последняя отмеченная водителями очередь по каждой
  // категории (см. handle_map_airports_api). Загружаются один раз при
  // открытии карты и обновляются реже позиций водителей - эти данные не
  // такие "живые".
  async function loadAirports() {{
    try {{
      const resp = await fetch(`/map/airports?city=${{encodeURIComponent(city)}}`);
      if (!resp.ok) return;
      const data = await resp.json();
      airportMarkers.forEach(m => map.removeLayer(m));
      airportMarkers = [];
      data.airports.forEach(a => {{
        // ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя): при высоком
        // спросе (загрузка >85% - тот же порог 🟣, что и в get_load_emoji
        // на сервере) рисуем вокруг аэропорта круг радиусом 3км, полупрозрачную
        // фиолетовую заливку - чтобы было видно ИЗДАЛЕКА на карте, не только
        // при клике на маркер. HIGH_DEMAND_LOAD_THRESHOLD держим в синхроне
        // с порогом >85 в get_load_emoji(main.py) - изменено 21.09.2026 (было 100).
        const HIGH_DEMAND_LOAD_THRESHOLD = 85;
        const HIGH_DEMAND_RADIUS_METERS = 3000;
        if (a.load !== null && a.load !== undefined && a.load > HIGH_DEMAND_LOAD_THRESHOLD) {{
          const circle = L.circle([a.lat, a.lon], {{
            radius: HIGH_DEMAND_RADIUS_METERS,
            color: '#9b30ff',
            weight: 2,
            fillColor: '#9b30ff',
            fillOpacity: 0.15,
          }}).addTo(map);
          airportMarkers.push(circle);
        }}
        const icon = L.divIcon({{ className: 'airport-icon', html: a.emoji || '✈️', iconSize: [26, 26] }});
        let popup = `<div class="airport-popup"><h4>${{a.emoji || '✈️'}} ${{a.name}}</h4>`;
        popup += `<div class="row">${{STATUS_ICON[a.status] || ''}} ${{a.status_text}}</div>`;
        if (a.load !== null && a.load !== undefined) {{
          popup += `<div class="row">📊 Загрузка сейчас: ${{a.load}}%</div>`;
        }}
        // ИСПРАВЛЕНО 20.09.2026 (жалоба пользователя - "надо разбить на
        // тарифы очереди, а не просто Ultima"): у категорий с тарифами
        // (Business/Premier/Elite/Cruise у Ultima и т.п.) сервер теперь
        // отдаёт queue[cat].by_tariff = {{tariff: {{range, local_time}}}}
        // вместо одной общей цифры на всю категорию - показываем каждый
        // тариф отдельной строкой. У категорий без тарифов формат остался
        // прежним (queue[cat] = {{range, local_time}}).
        const queueKeys = Object.keys(a.queue || {{}});
        let queueLines = [];
        queueKeys.forEach(key => {{
          const q = a.queue[key];
          const label = CATEGORY_LABEL[key] || key;
          if (q.by_tariff) {{
            Object.keys(q.by_tariff).forEach(tariff => {{
              const t = q.by_tariff[tariff];
              queueLines.push({{ text: `${{label}} ${{tariff}}: ${{t.range}} (на ${{t.local_time}})`, short: `${{tariff}}: ${{t.range}}` }});
            }});
          }} else {{
            queueLines.push({{ text: `${{label}}: ${{q.range}} (на ${{q.local_time}})`, short: `${{label}}: ${{q.range}}` }});
          }}
        }});
        if (queueLines.length) {{
          queueLines.forEach(q => {{ popup += `<div class="row">🚗 ${{q.text}}</div>`; }});
        }} else {{
          popup += `<div class="row">🚗 Очередь: свежих отметок нет</div>`;
        }}
        popup += `</div>`;
        // Постоянная подпись прямо на карте (без клика) - по просьбе
        // пользователя (22.09.2026): "так же отметь на карте", т.е. статус/
        // загрузка/очередь должны быть видны сразу, не только в попапе.
        let label = `<b>${{a.name}}</b><br>${{STATUS_ICON[a.status] || ''}} ${{a.status_text}}`;
        if (a.load !== null && a.load !== undefined) {{
          label += ` · 📊 ${{a.load}}%`;
        }}
        if (queueLines.length) {{
          label += '<br>' + queueLines.map(q => `🚗 ${{q.short}}`).join(' · ');
        }}
        const marker = L.marker([a.lat, a.lon], {{ icon }})
          .bindPopup(popup)
          .bindTooltip(label, {{ permanent: true, direction: 'right', offset: [10, 0], className: 'airport-label' }})
          .addTo(map);
        airportMarkers.push(marker);
      }});
      airportsLoaded = true;
    }} catch (e) {{ /* тихо */ }}
  }}
  // Вокзалы на карте (по просьбе пользователя, 21.09.2026 - "выведи на
  // карту жд вокзалы по типу аэропортов с процентом загрузки прибытия") -
  // та же идея, что loadAirports() выше, но проще: нет статуса Росавиации и
  // разбивки очереди по тарифам, только название + текущая загрузка %. У
  // вокзалов, в отличие от аэропортов, бинарная шкала (см. get_train_load_symbol
  // на сервере: >50% = 🟢 ехать, иначе 🔴 не ехать), поэтому порог для круга
  // повышенного спроса тоже 50%, а не 85% как у аэропортов.
  let stationMarkers = [];
  async function loadStations() {{
    try {{
      const resp = await fetch(`/map/stations?city=${{encodeURIComponent(city)}}`);
      if (!resp.ok) return;
      const data = await resp.json();
      stationMarkers.forEach(m => map.removeLayer(m));
      stationMarkers = [];
      data.stations.forEach(s => {{
        const STATION_HIGH_LOAD_THRESHOLD = 50;
        if (s.load !== null && s.load !== undefined && s.load > STATION_HIGH_LOAD_THRESHOLD) {{
          const circle = L.circle([s.lat, s.lon], {{
            radius: 1500,
            color: '#2e7d32',
            weight: 2,
            fillColor: '#2e7d32',
            fillOpacity: 0.15,
          }}).addTo(map);
          stationMarkers.push(circle);
        }}
        const icon = L.divIcon({{ className: 'airport-icon', html: '🚆', iconSize: [26, 26] }});
        const symbol = (s.load !== null && s.load !== undefined && s.load > STATION_HIGH_LOAD_THRESHOLD) ? '🟢' : '🔴';
        let popup = `<div class="airport-popup"><h4>🚆 ${{s.name}}</h4>`;
        if (s.load !== null && s.load !== undefined) {{
          popup += `<div class="row">📊 Загрузка сейчас: ${{s.load}}% ${{symbol}}</div>`;
        }}
        popup += `</div>`;
        let label = `<b>${{s.name}}</b>`;
        if (s.load !== null && s.load !== undefined) {{
          label += `<br>📊 ${{s.load}}% ${{symbol}}`;
        }}
        const marker = L.marker([s.lat, s.lon], {{ icon }})
          .bindPopup(popup)
          .bindTooltip(label, {{ permanent: true, direction: 'right', offset: [10, 0], className: 'airport-label' }})
          .addTo(map);
        stationMarkers.push(marker);
      }});
    }} catch (e) {{ /* тихо */ }}
  }}
  // Дорожные события (ДТП/перекрытия) с распознанным адресом - по просьбе
  // пользователя (22.09.2026): "вынеси на карту дорожные события города где
  // есть адреса". События без адреса в тексте поста не геокодируются на
  // сервере и сюда не попадают вовсе (см. handle_map_road_events_api) - на
  // карте видны только те, для которых удалось определить точку.
  let roadEventMarkers = [];
  function roadEventIcon(ev) {{
    if (ev.is_severe) return '🚑';
    if (ev.is_closure) return '⛔';
    return '⚠️';
  }}
  async function loadRoadEvents() {{
    try {{
      const resp = await fetch(`/map/road_events?city=${{encodeURIComponent(city)}}`);
      if (!resp.ok) return;
      const data = await resp.json();
      roadEventMarkers.forEach(m => map.removeLayer(m));
      roadEventMarkers = [];
      data.events.forEach(ev => {{
        const icon = L.divIcon({{ className: 'road-icon', html: roadEventIcon(ev), iconSize: [22, 22] }});
        let popup = `<div class="road-popup">`;
        if (ev.address) popup += `<b>${{ev.address}}</b><br>`;
        popup += `${{(ev.text || '').replace(/\\n/g, '<br>')}}`;
        if (ev.link) popup += `<br><a href="${{ev.link}}" target="_blank">Открыть пост</a>`;
        if (ev.time) {{
          const t = new Date(ev.time);
          popup += `<div class="time">${{t.toLocaleTimeString('ru-RU', {{ hour: '2-digit', minute: '2-digit' }})}}</div>`;
        }}
        popup += `</div>`;
        const marker = L.marker([ev.lat, ev.lon], {{ icon }}).bindPopup(popup).addTo(map);
        roadEventMarkers.push(marker);
      }});
    }} catch (e) {{ /* тихо */ }}
  }}
  // Афиша (концерты/мероприятия) с геокодированной площадкой - по просьбе
  // пользователя (22.09.2026): "Афишу тоже выноси". Как и дорожные события,
  // события без распознанного/геокодированного места сюда не попадают (см.
  // handle_map_city_events_api) - только те, для которых известна точка.
  let cityEventMarkers = [];
  function formatEventStart(ev) {{
    const d = ev.start_is_ts ? new Date(ev.start * 1000) : new Date(ev.start);
    if (isNaN(d.getTime())) return '';
    return d.toLocaleString('ru-RU', {{ day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }});
  }}
  async function loadCityEvents() {{
    try {{
      const resp = await fetch(`/map/city_events?city=${{encodeURIComponent(city)}}`);
      if (!resp.ok) return;
      const data = await resp.json();
      cityEventMarkers.forEach(m => map.removeLayer(m));
      cityEventMarkers = [];
      data.events.forEach(ev => {{
        const icon = L.divIcon({{ className: 'event-icon', html: '🎭', iconSize: [22, 22] }});
        let popup = `<div class="event-popup">`;
        if (ev.title) popup += `<h4>${{ev.title}}</h4>`;
        if (ev.place) popup += `<div class="place">${{ev.place}}</div>`;
        if (ev.start) popup += `<div class="time">${{formatEventStart(ev)}}</div>`;
        if (ev.link) popup += `<br><a href="${{ev.link}}" target="_blank">Подробнее</a>`;
        popup += `</div>`;
        const marker = L.marker([ev.lat, ev.lon], {{ icon }}).bindPopup(popup).addTo(map);
        cityEventMarkers.push(marker);
      }});
    }} catch (e) {{ /* тихо */ }}
  }}
  loadPositions();
  loadAirports();
  loadStations();
  loadRoadEvents();
  loadCityEvents();
  setInterval(loadPositions, 15000);
  // ИЗМЕНЕНО 21.09.2026 (жалоба пользователя - новое перекрытие пришло
  // пушем в чат мгновенно, но не появилось на карте): было 120000 (2 мин),
  // теперь опрашиваем каждые 30с - вместе с ускоренным сбором на сервере
  // (ROAD_EVENTS_UPDATE_INTERVAL_MINUTES 10->2 мин, см. main.py) свежее
  // событие теперь доходит до карты за секунды-минуты, а не до ~12 минут.
  setInterval(loadRoadEvents, 30000);
  setInterval(loadAirports, 60000);
  setInterval(loadStations, 60000);
  setInterval(loadCityEvents, 300000);
</script>
</body>
</html>"""

async def handle_map_webapp(request):
    # Telegram WebView иногда агрессивно кэширует открытую внутри мини-аппа
    # страницу - по жалобе пользователя (22.09.2026, "карта не открывается,
    # белого цвета") добавлены заголовки против кэширования, чтобы после
    # редеплоя водитель гарантированно получал свежую версию страницы, а не
    # старую закэшированную (в т.ч. со старым багом в JS).
    return web.Response(
        text=map_webapp_html(), content_type='text/html',
        headers={'Cache-Control': 'no-store, no-cache, must-revalidate', 'Pragma': 'no-cache'},
    )

async def handle_map_positions_api(request):
    """JSON API для карты - отдаёт только category/lat/lon (без user_id),
    проверяя подпись initData, если задан BOT_TOKEN. Если initData
    отсутствует/невалиден - всё равно отдаём данные (это не платёжный webhook,
    а публичная агрегированная карта без персональных данных), но логируем,
    чтобы отследить аномальный трафик. Параметр category (опциональный) -
    фильтр по категории (по просьбе пользователя, 21.09.2026 - своя категория
    по умолчанию, см. get_map_positions/map_webapp_html); пустой или
    отсутствующий - вся карта."""
    city = request.query.get('city', '')
    category = request.query.get('category', '') or None
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    if BOT_TOKEN and init_data:
        if validate_telegram_webapp_init_data(init_data, BOT_TOKEN) is None:
            logger.warning("⚠️ /map/positions: не прошла проверка initData")
    try:
        positions = get_map_positions(city, category) if city else []
        # Тарифы уже человекочитаемые строки (см. CATEGORIES[cat]['tariffs'] /
        # shift_tariff_options) - WebApp просто склеивает их через запятую в
        # подписи маркера (см. map_webapp_html), переводить не нужно.
    except Exception:
        logger.exception("❌ Ошибка при получении позиций для карты водителей")
        positions = []
    return web.json_response({'positions': positions})

async def handle_map_airports_api(request):
    """JSON API для меток аэропортов на карте (по просьбе пользователя,
    22.09.2026): название, координаты, статус Росавиации (открыт/по
    согласованию/закрыт), текущая загрузка % и последняя отмеченная
    водителями очередь по каждой категории (такси/Ultima). Публичные
    агрегированные данные, initData не обязателен (как и у /map/positions)."""
    city = request.query.get('city', '')
    result = []
    try:
        for airport in AIRPORTS_INFO.get(city, []):
            icao = airport['icao']
            zone_key = airport.get('zone_key')
            # ИСПРАВЛЕНО 20.09.2026 (жалоба пользователя - на карте Шереметьево
            # B/C и D были одной точкой вместо двух): раньше тут всегда брались
            # координаты AIRPORT_COORDS[icao] - усреднённая точка ВСЕГО
            # аэропорта, одна и та же для обеих терминальных записей (у
            # Шереметьево zone_key='bc' и zone_key='d' имеют одинаковый icao
            # UUEE, см. AIRPORT_TERMINAL_ZONES) - поэтому оба маркера
            # накладывались друг на друга и выглядели как один. Теперь, если у
            # записи есть zone_key, берём координаты именно этой зоны (те же,
            # что уже используются для "Очередь у аэропорта" - см.
            # nearest_airport_zone) - маркеры расходятся по факту на карте, как
            # и сами терминалы физически разнесены.
            zone_coords = AIRPORT_TERMINAL_ZONES.get(icao, {}).get(zone_key, {}).get('coords') if zone_key else None
            coords = zone_coords or AIRPORT_COORDS.get(icao)
            if not coords:
                continue
            entry = {
                'name': airport['name'], 'emoji': airport.get('emoji', '✈️'),
                'icao': icao, 'lat': coords[0], 'lon': coords[1],
            }
            if airport.get('closed'):
                entry['status'] = 'closed'
                entry['status_text'] = 'ЗАКРЫТ'
                entry['load'] = None
            else:
                status, _ = get_airport_status(icao)
                _icon, status_text = AIRPORT_STATUS_DISPLAY[status]
                entry['status'] = status
                entry['status_text'] = status_text
                try:
                    info = compute_current_availability(icao, 'total', zone_key=airport.get('zone_key'))
                    entry['load'] = round(info['load'])
                except Exception:
                    entry['load'] = None
            # ИСПРАВЛЕНО 20.09.2026 (жалоба пользователя - "тут надо разбить
            # на тарифы очереди, а не просто Ultima"): раньше очередь на
            # карте показывалась ОДНОЙ общей цифрой на всю категорию
            # (queue_latest_report_for_category), хотя у категории может
            # быть несколько тарифов с РАЗНОЙ очередью (Business/Premier/
            # Elite/Cruise у Ultima) - водитель на Premier видел цифру,
            # которая на самом деле могла быть от чьей-то отметки на Elite.
            # Теперь для категорий с тарифами (CATEGORIES[cat]['tariffs'])
            # берём отметку ПО КАЖДОМУ тарифу отдельно (queue_latest_report с
            # ключом "категория:тариф", тот же ключ, что пишет
            # queue_submit_report/submit_range) - на карте будет видно,
            # например, "Premier: 11-15" и "Business: нет свежих отметок"
            # раздельно, а не одна усреднённая строка на всю Ultima.
            queue = {}
            for category in MAP_AIRPORT_QUEUE_CATEGORIES:
                tariffs = CATEGORIES.get(category, {}).get('tariffs') or []
                if tariffs:
                    by_tariff = {}
                    for tariff in tariffs:
                        range_str, ts = queue_latest_report(city, icao, f"{category}:{tariff}", zone_key=zone_key)
                        if range_str:
                            by_tariff[tariff] = {'range': range_str, 'local_time': format_airport_local_time(ts, icao)}
                    if by_tariff:
                        queue[category] = {'by_tariff': by_tariff}
                else:
                    range_str, ts = queue_latest_report_for_category(city, icao, category, zone_key=zone_key)
                    if range_str:
                        queue[category] = {'range': range_str, 'local_time': format_airport_local_time(ts, icao)}
            entry['queue'] = queue
            result.append(entry)
    except Exception:
        logger.exception("❌ Ошибка при получении аэропортов для карты водителей")
        result = []
    return web.json_response({'airports': result})

MAP_STATIONS_API_PATH = '/map/stations'

async def handle_map_stations_api(request):
    """JSON API для меток вокзалов на карте (по просьбе пользователя,
    21.09.2026 - "выведи на карту жд вокзалы по типу аэропортов с процентом
    загрузки прибытия"): та же идея, что handle_map_airports_api, но проще -
    у вокзалов нет статуса Росавиации и разбивки очереди по тарифам, только
    название, координаты и текущая загрузка % (см. get_train_load_symbol -
    та же бинарная шкала, что в разделе "Вокзалы"). Публичные агрегированные
    данные, initData не обязателен (как и у /map/airports)."""
    city = request.query.get('city', '')
    result = []
    try:
        for station in STATIONS_INFO.get(city, []):
            code = station['code']
            coords = STATION_COORDS.get(code)
            if not coords:
                continue
            entry = {
                'name': station['name'], 'code': code,
                'lat': coords[0], 'lon': coords[1],
            }
            try:
                load, _trains, _ = compute_current_train_period_load(code, 'taxi')
                entry['load'] = round(load)
            except Exception:
                entry['load'] = None
            result.append(entry)
    except Exception:
        logger.exception("❌ Ошибка при получении вокзалов для карты водителей")
        result = []
    return web.json_response({'stations': result})

MAP_ROAD_EVENTS_API_PATH = '/map/road_events'

# ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя - "на карте события долго
# не висели, чтобы её не захламлять"): раньше метка на карте жила ровно
# столько же, сколько событие оставалось в общих данных (LOOKBACK_HOURS в
# fetch_road_events.py, тогда 6ч на оба типа сразу). Теперь у карты СВОЙ,
# более короткий и разный по типу порог - перекрытие (is_closure=True)
# важнее и актуальнее дольше (объезд нужен, пока не сняли), поэтому висит
# дольше, а обычная авария (без признака перекрытия) обычно расчищается
# быстро - снимается с карты уже через 3ч, чтобы не захламлять её старыми
# метками. Данные при этом собираются (fetch_road_events.py) с окном 24ч -
# этого достаточно с запасом для более долгого TTL перекрытий.
MAP_CLOSURE_TTL_HOURS = 24
MAP_INCIDENT_TTL_HOURS = 3

async def handle_map_road_events_api(request):
    """JSON API для меток дорожных событий на карте (по просьбе пользователя,
    22.09.2026: "вынеси на карту дорожные события города где есть адреса") -
    отдаёт только те события из get_road_events_for_city, для которых
    удалось распознать и геокодировать адрес в тексте поста (см.
    extract_address/geocode_notices в fetch_road_events.py) - у остальных
    просто нет lat/lon, на карту они и не должны попадать. Полный список (в
    т.ч. без адреса) по-прежнему доступен в обычной кнопке "⛔ Дорожные
    события" внутри бота (у него СВОЙ, отдельный порог - см.
    ROAD_EVENTS_CHAT_LOOKBACK_HOURS - на эту функцию не влияет).

    TTL на карте различается по типу события - см. MAP_CLOSURE_TTL_HOURS/
    MAP_INCIDENT_TTL_HOURS выше."""
    city = request.query.get('city', '')
    now = datetime.now(ZoneInfo('UTC'))
    closure_cutoff = (now - timedelta(hours=MAP_CLOSURE_TTL_HOURS)).isoformat()
    incident_cutoff = (now - timedelta(hours=MAP_INCIDENT_TTL_HOURS)).isoformat()
    result = []
    try:
        for event in get_road_events_for_city(city):
            lat, lon = event.get('lat'), event.get('lon')
            if lat is None or lon is None:
                continue
            is_closure = bool(event.get('is_closure'))
            event_time = event.get('time', '')
            cutoff = closure_cutoff if is_closure else incident_cutoff
            if event_time < cutoff:
                continue  # событие старше своего TTL для карты - не показываем, чтобы не захламлять
            result.append({
                'lat': lat, 'lon': lon, 'address': event.get('address'),
                'text': event.get('text', ''), 'time': event.get('time'),
                'link': event.get('link'), 'is_closure': is_closure,
                'is_severe': bool(event.get('is_severe')),
            })
    except Exception:
        logger.exception("❌ Ошибка при получении дорожных событий для карты водителей")
        result = []
    return web.json_response({'events': result})

MAP_CITY_EVENTS_API_PATH = '/map/city_events'

# ИЗМЕНЕНО 21.09.2026 (та же просьба пользователя, что и у дорожных событий -
# "на карте события долго не висели, чтобы её не захламлять"): раньше метка
# афиши появлялась на карте СРАЗУ, как только событие попадало в данные
# (могло быть за дни/недели до начала) и висела до самого начала. Теперь
# метка появляется на карте только за MAP_EVENT_ADVANCE_HOURS до начала -
# не раньше, чтобы не захламлять карту событиями, которые будут ещё очень
# нескоро. Исчезает по-прежнему ровно в момент начала (now_ts >= start).
MAP_EVENT_ADVANCE_HOURS = 3

async def handle_map_city_events_api(request):
    """JSON API для меток афиши (концерты/мероприятия) на карте - по просьбе
    пользователя (22.09.2026, следом за дорожными событиями): "Афишу тоже
    выноси". Два источника, оба уже читаются в боте (см. get_events_for_user
    для TimePad и get_concert_events_for_city для Telegram-каналов) -
    отдаём ТОЛЬКО события, для которых при сборе удалось геокодировать
    площадку/адрес (см. geocode_posts в fetch_concert_events.py и
    geocode_events в fetch_timepad_data.py) - события без координат на карту
    не попадают, но остаются в обычном разделе "🎭 События города" внутри
    бота. На карте видны только события в окне [сейчас; +MAP_EVENT_ADVANCE_HOURS]
    (см. MAP_EVENT_ADVANCE_HOURS выше) - не раньше и не позже, чтобы не
    захламлять карту метками далёких во времени мероприятий."""
    city = request.query.get('city', '')
    now_ts = datetime.now(ZoneInfo('UTC')).timestamp()
    advance_cutoff_ts = now_ts + MAP_EVENT_ADVANCE_HOURS * 3600
    result = []
    try:
        timepad_data = load_timepad_data()
        for ev in (timepad_data or {}).get('cities', {}).get(city, []):
            lat, lon = ev.get('place_lat'), ev.get('place_lon')
            start = ev.get('start') or 0
            if lat is None or lon is None or start < now_ts or start > advance_cutoff_ts:
                continue
            result.append({
                'lat': lat, 'lon': lon, 'title': ev.get('title') or '',
                'place': ev.get('place_address') or '', 'start': ev.get('start'),
                'start_is_ts': True, 'link': ev.get('url'),
            })
        for post in get_concert_events_for_city(city):
            lat, lon = post.get('lat'), post.get('lon')
            if lat is None or lon is None:
                continue
            start_iso = post.get('start')
            if start_iso:
                try:
                    start_ts = datetime.fromisoformat(start_iso).timestamp()
                    if start_ts < now_ts or start_ts > advance_cutoff_ts:
                        continue
                except Exception:
                    pass
            result.append({
                'lat': lat, 'lon': lon, 'title': post.get('title') or '',
                'place': post.get('place') or '', 'start': start_iso,
                'start_is_ts': False, 'link': post.get('link'),
            })
    except Exception:
        logger.exception("❌ Ошибка при получении афиши для карты водителей")
        result = []
    return web.json_response({'events': result})

@router.message(lambda message: getattr(message, 'location', None) is not None and not _location_tracking_active(message.from_user.id) and not user_state.get(message.from_user.id, {}).get('nearby_pending'))
async def handle_passive_live_location(message: types.Message):
    """По жалобе пользователя (20.09.2026): "сверху уже включен сбор
    локации... а он опять запрашивает" - водитель мог включить трансляцию
    живой геопозиции в Telegram САМ (не через кнопку бота "Очередь у
    аэропорта"/"Начать смену"), и тогда ни одна из наших фич не активна
    (_location_tracking_active=False), а значит наши хендлеры пингов вообще
    не видят эту трансляцию. Этот пассивный хендлер просто запоминает
    координаты (см. remember_live_location/get_fresh_live_location) на
    случай, если дальше бот захочет предложить включить "Очередь у
    аэропорта" или найти ближайшие точки - чтобы не спрашивать геопозицию
    повторно, раз она и так уже транслируется. Ничего не отвечает - не хотим
    присылать лишнее сообщение на каждый пинг трансляции, о которой бот
    формально не просил."""
    remember_live_location(message.from_user.id, message.location.latitude, message.location.longitude)

@router.edited_message(lambda message: getattr(message, 'location', None) is not None and not _location_tracking_active(message.from_user.id))
async def handle_passive_live_location_update(message: types.Message):
    """Обновления той же самостоятельно включённой трансляции - см.
    handle_passive_live_location."""
    remember_live_location(message.from_user.id, message.location.latitude, message.location.longitude)

@router.message(lambda message: getattr(message, 'location', None) is not None and _location_tracking_active(message.from_user.id) and not user_state.get(message.from_user.id, {}).get('nearby_pending'))
async def handle_airport_queue_location(message: types.Message):
    """Срабатывает только на ПЕРВЫЙ пинг живой геопозиции (сама отправка -
    обычное новое сообщение); все следующие обновления той же трансляции
    приходят как edited_message, см. handle_airport_queue_location_update
    ниже - отдельный хендлер их не трогает. Поэтому именно тут (а не там)
    место для разового "геопозиция получена" - по просьбе пользователя,
    чтобы после отправки геопозиции чат не оставался без клавиатуры меню.
    Обслуживает ОБЕ фичи на живой геопозиции (очередь у аэропорта и счётчик
    км, см. _location_tracking_active) - они независимы, каждая читает один
    и тот же пинг своей функцией (process_airport_queue_ping/km_counter_ping)
    и просто ничего не делает, если сама выключена (см. их код).

    БАГФИКС: "and not ...nearby_pending" в фильтре обязателен. Кнопки
    "🚻 Туалеты"/"🚿 Мойки"/и т.п. (см. show_nearby_prompt/handle_nearby_location
    ниже) просят разовую геопозицию тем же способом - обычным
    message.location. Без этого условия, если у водителя уже включена
    "Очередь у аэропорта" (airport_queue_active=True) и он ОДНОВРЕМЕННО
    ищет, например, туалеты, aiogram матчит хендлеры по порядку регистрации
    и останавливается на первом подошедшем - этот хендлер (зарегистрирован
    раньше handle_nearby_location) перехватывал сообщение с геопозицией
    целиком: вместо списка туалетов/моек пользователь видел пуш про
    аэропорт, а handle_nearby_location вообще не срабатывал. Теперь, пока
    nearby_pending активен (разовый запрос геопозиции для другой кнопки в
    процессе), эта конкретная геопозиция достаётся ЕМУ, а не отслеживанию
    очереди - следующий пинг живой трансляции (edited_message,
    handle_airport_queue_location_update ниже, её этот фильтр не касается)
    обработается как обычно."""
    user_id = message.from_user.id
    lat, lon = message.location.latitude, message.location.longitude
    await process_airport_queue_ping(user_id, lat, lon, live_period=getattr(message.location, 'live_period', None))
    km_counter_ping(user_id, lat, lon)
    remember_live_location(user_id, lat, lon)
    maybe_update_map_position(user_id, lat, lon)
    state = user_state.get(user_id) or {}
    if state.get('airport_queue_active') and is_shift_active(state):
        status_text = "📍 Геопозиция получена, слежу за очередью и считаю километраж смены."
    elif state.get('airport_queue_active'):
        status_text = "📍 Геопозиция получена, слежу за расстоянием до аэропорта."
    else:
        status_text = "📍 Геопозиция получена, считаю километраж смены."
    await message.answer(status_text, reply_markup=services_keyboard(state.get('category'), state.get('city'), user_id))

@router.edited_message(lambda message: getattr(message, 'location', None) is not None and _location_tracking_active(message.from_user.id))
async def handle_airport_queue_location_update(message: types.Message):
    """Дальнейшие обновления живой геопозиции приходят в Telegram НЕ новыми
    сообщениями, а правками (edit) первого - отдельный апдейт edited_message,
    поэтому отдельный хендлер (обычный @router.message его не ловит).
    Обслуживает обе фичи на живой геопозиции - см. комментарий у
    handle_airport_queue_location."""
    user_id = message.from_user.id
    lat, lon = message.location.latitude, message.location.longitude
    await process_airport_queue_ping(user_id, lat, lon, live_period=getattr(message.location, 'live_period', None))
    km_counter_ping(user_id, lat, lon)
    remember_live_location(user_id, lat, lon)
    maybe_update_map_position(user_id, lat, lon)

@router.message(lambda message: message.text in NEARBY_BUTTON_TO_KIND and user_state.get(message.from_user.id, {}).get('in_courier_module'))
async def show_nearby_prompt(message: types.Message):
    """Нажатие на "🚻 Туалеты"/"🅿️ Парковка"/"🔧 Шиномонтаж"/
    "🚿 Мойки" - запрашивает у водителя геолокацию (кнопка request_location в
    nearby_location_keyboard). Сама выдача ближайших точек - в
    handle_nearby_location ниже, после того как Telegram пришлёт location.

    По просьбе пользователя (20.09.2026: "чтоб он тоже не запрашивал а брал
    из данных трансляции") - если у водителя уже активна трансляция живой
    геопозиции (очередь у аэропорта/смена) и последняя точка свежая (см.
    get_fresh_live_location), сразу показываем результаты по ней, не спрашивая
    геопозицию заново."""
    user_id = message.from_user.id
    kind = NEARBY_BUTTON_TO_KIND[message.text]
    fresh = get_fresh_live_location(user_id)
    if fresh:
        lat, lon = fresh
        await send_nearby_results(message, user_id, kind, lat, lon)
        return
    user_state[user_id]['nearby_pending'] = kind
    cfg = NEARBY_SERVICES[kind]
    await message.answer(
        f"{cfg['emoji']} Отправь геолокацию, чтобы найти ближайшие {cfg['noun']} 👇",
        reply_markup=nearby_location_keyboard(),
    )

@router.message(lambda message: user_state.get(message.from_user.id, {}).get('nearby_pending') and message.text == "❌ Отмена")
async def cancel_nearby_prompt(message: types.Message):
    user_id = message.from_user.id
    category = user_state[user_id].get('category')
    user_state[user_id].pop('nearby_pending', None)
    await message.answer("Отменено", reply_markup=courier_module_keyboard(category))

async def send_nearby_results(message: types.Message, user_id, kind, lat, lon):
    """Общая логика показа ближайших точек (Туалеты/Парковка/Шиномонтаж/
    Мойки/...) - вынесена из handle_nearby_location, чтобы её же мог вызвать
    show_nearby_prompt напрямую, если уже есть свежая живая геопозиция (см.
    get_fresh_live_location), без запроса геолокации у водителя. Считает
    ближайшие NEARBY_RESULTS_COUNT точек по прямой (haversine_km) и
    показывает список с кнопками "Поехали" (маршрут в Яндекс Навигаторе на
    каждую). Reply-клавиатуру (нижнее меню) и инлайн-кнопки результатов
    Telegram нельзя отправить одним сообщением - поэтому два отдельных
    answer(): сначала возвращаем обычное меню инструментов, потом отдельным
    сообщением - сам список с инлайн-кнопками."""
    state = user_state[user_id]
    city = state.get('city')
    cfg = NEARBY_SERVICES[kind]

    scored = nearest_nearby_points(kind, city, lat, lon)
    if scored is None:
        await message.answer(
            f"{cfg['emoji']} Данные по разделу «{cfg['label']}» пока не собраны - скоро добавим.",
            reply_markup=courier_module_keyboard(state.get('category')),
        )
        return
    if not scored:
        await message.answer(
            f"{cfg['emoji']} Для твоего города пока нет собранных точек «{cfg['label']}» - сбор идёт постепенно по городам, скоро дойдём и до тебя.",
            reply_markup=courier_module_keyboard(state.get('category')),
        )
        return

    text, keyboard = render_nearby_results(kind, scored)
    await message.answer("Готово 👇", reply_markup=courier_module_keyboard(state.get('category')))
    try:
        await message.answer(text, reply_markup=keyboard, parse_mode='Markdown')
    except Exception as e:
        # Уже был реальный случай: невалидная ссылка в кнопке "Поехали"
        # (кастомная схема yandexnavi://) роняла именно ЭТО сообщение молча -
        # первое ("Готово") доходило, а сам список точек пропадал без всякой
        # ошибки в чате. Больше так не должно случиться ни по какой причине -
        # если что-то всё же сломается, водитель хотя бы получит понятный
        # текст вместо тишины, а в логах будет видно, что упало и почему.
        logger.error(f"❌ Не удалось отправить список точек «{kind}» пользователю {user_id}: {e}")
        await message.answer(
            f"{cfg['emoji']} Не получилось показать список - попробуй ещё раз через минуту.",
        )

@router.message(lambda message: getattr(message, 'location', None) is not None and user_state.get(message.from_user.id, {}).get('nearby_pending'))
async def handle_nearby_location(message: types.Message):
    """Водитель прислал геолокацию (кнопка "📍 Отправить геолокацию") после
    show_nearby_prompt - см. send_nearby_results для самой логики показа."""
    user_id = message.from_user.id
    state = user_state[user_id]
    kind = state.pop('nearby_pending')
    lat, lon = message.location.latitude, message.location.longitude
    await send_nearby_results(message, user_id, kind, lat, lon)

@router.callback_query(lambda c: c.data == "show_shift_stats")
async def show_shift_stats(callback_query: types.CallbackQuery):
    """"📈 Статистика смен" - инлайн-кнопка под первым шагом "💰 Финансы" (см.
    start_courier_finance). Показывает итоги за неделю/месяц/6 месяцев плюс
    последние 14 дней по дням - вся история хранится в БД 6 месяцев (см.
    get_shift_history/SHIFT_HISTORY_MONTHS), но выводить построчно все ~180
    дней в одном сообщении Telegram не даст (лимит 4096 символов) и это
    бесполезно много для водителя - итогов за периоды + недавних дней
    достаточно, чтобы понимать динамику."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    rows = get_shift_history(user_id)  # [(shift_date, duration_minutes, km, airport_wait_minutes), ...] за 6 месяцев, новые сверху

    if not rows:
        await callback_query.message.answer(
            "📈 *Статистика смен*\n\nПока нет ни одной завершённой смены - начни смену кнопкой «▶️ Начать смену» в главном меню.",
            parse_mode='Markdown',
        )
        return

    # Группируем по дню (за один день может быть несколько смен).
    by_day = {}
    for shift_date, duration_minutes, km, airport_wait_minutes in rows:
        agg = by_day.setdefault(shift_date, {'minutes': 0, 'km': 0.0})
        agg['minutes'] += duration_minutes
        agg['km'] += km
    days_sorted = sorted(by_day.keys(), reverse=True)

    today_str = datetime.now(timezone.utc).date().isoformat()
    week_cutoff = (datetime.now(timezone.utc).date() - timedelta(days=7)).isoformat()
    month_cutoff = (datetime.now(timezone.utc).date() - timedelta(days=30)).isoformat()

    def sum_period(cutoff):
        minutes = sum(agg['minutes'] for d, agg in by_day.items() if d >= cutoff)
        km = sum(agg['km'] for d, agg in by_day.items() if d >= cutoff)
        return minutes, km

    week_minutes, week_km = sum_period(week_cutoff)
    month_minutes, month_km = sum_period(month_cutoff)
    total_minutes = sum(agg['minutes'] for agg in by_day.values())
    total_km = sum(agg['km'] for agg in by_day.values())

    lines = [
        "📈 *Статистика смен*",
        "",
        f"За 7 дней: {format_shift_duration(week_minutes)}, {week_km:.0f} км",
        f"За 30 дней: {format_shift_duration(month_minutes)}, {month_km:.0f} км",
        f"За {SHIFT_HISTORY_MONTHS} мес.: {format_shift_duration(total_minutes)}, {total_km:.0f} км",
        "",
        "*Последние дни:*",
    ]
    for d in days_sorted[:14]:
        agg = by_day[d]
        label = "Сегодня" if d == today_str else d
        lines.append(f"{label}: {format_shift_duration(agg['minutes'])}, {agg['km']:.0f} км")

    text = '\n'.join(lines)
    if len(text) > 4000:
        text = text[:4000] + "…"
    await callback_query.message.answer(
        text,
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="📊 По дням недели / неделям / месяцам", callback_data="show_shift_breakdown"),
        ]]),
        parse_mode='Markdown',
    )

@router.callback_query(lambda c: c.data == "show_shift_breakdown")
async def show_shift_breakdown(callback_query: types.CallbackQuery):
    """Разбивка статистики смен (по просьбе пользователя, 20.09.2026):
    - по дням недели (понедельник..воскресенье) - суммарно за все 6 месяцев,
      чтобы видеть, какие дни недели самые "рабочие"/прибыльные;
    - по неделям (последние 8 недель, начало недели - понедельник);
    - по месяцам (последние 6 календарных месяцев).
    Отдельная кнопка под "📈 Статистика смен", чтобы не перегружать основной
    экран - он уже показывает итоги за 7/30/180 дней и последние дни."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    rows = get_shift_history(user_id)  # [(shift_date, duration_minutes, km, airport_wait_minutes), ...] за 6 месяцев

    if not rows:
        await callback_query.message.answer(
            "📊 Пока нет ни одной завершённой смены - начни смену кнопкой «✅ НАЧАТЬ СМЕНУ» в главном меню.",
        )
        return

    by_day = {}
    for shift_date, duration_minutes, km, airport_wait_minutes in rows:
        agg = by_day.setdefault(shift_date, {'minutes': 0, 'km': 0.0})
        agg['minutes'] += duration_minutes
        agg['km'] += km

    # --- По дням недели ---
    by_weekday = {i: {'minutes': 0, 'km': 0.0, 'days': 0} for i in range(7)}
    for d, agg in by_day.items():
        wd = datetime.fromisoformat(d).weekday()
        by_weekday[wd]['minutes'] += agg['minutes']
        by_weekday[wd]['km'] += agg['km']
        by_weekday[wd]['days'] += 1

    lines = ["📊 *Статистика по дням недели, неделям и месяцам*", "", "*По дням недели (за 6 мес.):*"]
    for wd in range(7):
        agg = by_weekday[wd]
        if agg['days'] == 0:
            continue
        avg_minutes = round(agg['minutes'] / agg['days'])
        lines.append(
            f"{RU_WEEKDAYS[wd].capitalize()}: {format_shift_duration(agg['minutes'])}, {agg['km']:.0f} км "
            f"({agg['days']} см., в среднем {format_shift_duration(avg_minutes)})"
        )

    # --- По неделям (последние 8, начиная с текущей) ---
    def week_start(date_obj):
        return date_obj - timedelta(days=date_obj.weekday())

    by_week = {}
    for d, agg in by_day.items():
        ws = week_start(datetime.fromisoformat(d).date())
        wk = by_week.setdefault(ws, {'minutes': 0, 'km': 0.0})
        wk['minutes'] += agg['minutes']
        wk['km'] += agg['km']
    weeks_sorted = sorted(by_week.keys(), reverse=True)[:8]

    lines.append("")
    lines.append("*По неделям (последние 8):*")
    for ws in weeks_sorted:
        agg = by_week[ws]
        we = ws + timedelta(days=6)
        lines.append(f"{ws.strftime('%d.%m')}–{we.strftime('%d.%m')}: {format_shift_duration(agg['minutes'])}, {agg['km']:.0f} км")

    # --- По месяцам (последние 6 календарных) ---
    RU_MONTHS = ('января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря')
    by_month = {}
    for d, agg in by_day.items():
        date_obj = datetime.fromisoformat(d).date()
        mk = (date_obj.year, date_obj.month)
        m = by_month.setdefault(mk, {'minutes': 0, 'km': 0.0})
        m['minutes'] += agg['minutes']
        m['km'] += agg['km']
    months_sorted = sorted(by_month.keys(), reverse=True)[:6]

    lines.append("")
    lines.append("*По месяцам:*")
    for (year, month) in months_sorted:
        agg = by_month[(year, month)]
        lines.append(f"{RU_MONTHS[month - 1].capitalize()}: {format_shift_duration(agg['minutes'])}, {agg['km']:.0f} км")

    text = '\n'.join(lines)
    if len(text) > 4000:
        text = text[:4000] + "…"
    await callback_query.message.answer(text, parse_mode='Markdown')

def today_shift_totals(user_id):
    """Суммарные км/минуты/минуты простоя в аэропорту по ЗАВЕРШЁННЫМ сегодня
    сменам (см. save_shift_record) - используется, чтобы автоматически
    подставить километраж и часы смены в расчёт финансов (по просьбе
    пользователя, 20.09.2026: "время смены и часовой берётся из данных по
    кнопке начала смены"), не спрашивая их у водителя повторно. Смена,
    которая ещё ИДЁТ прямо сейчас, сюда не попадает - учитываются только уже
    завершённые (см. finish_shift)."""
    today_str = datetime.now(timezone.utc).date().isoformat()
    rows = get_shift_history(user_id, months=1)
    today_rows = [r for r in rows if r[0] == today_str]
    return {
        'km': sum(r[2] for r in today_rows),
        'minutes': sum(r[1] for r in today_rows),
        'airport_wait_minutes': sum(r[3] for r in today_rows),
    }

@router.callback_query(lambda c: c.data == "start_finance_after_shift")
async def start_finance_after_shift(callback_query: types.CallbackQuery):
    """Кнопка "💰 Указать доход за день" под сообщением "СМЕНА ЗАВЕРШЕНА" (по
    просьбе пользователя, 20.09.2026, см. toggle_shift) - запускает тот же
    пошаговый расчёт, что и обычная кнопка "💰 Финансы" (start_courier_finance),
    сразу с шага "Доход". Km за смену уже известен (только что завершилась) -
    подставится автоматически на шаге "Километраж" кнопкой "✅ Использовать N
    км", как и при обычном заходе в финансы (см. today_shifts_km)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    state['courier_finance_draft'] = {'step': 'income', 'data': {}}
    await callback_query.message.answer(COURIER_FINANCE_STEP_PROMPTS['income'], reply_markup=courier_finance_cancel_keyboard())

async def advance_finance_step(target, user_id, state, draft):
    """Переводит черновик на следующий шаг и отправляет его промпт - общий
    код для courier_finance_flow (текстовый ввод) и колбэков "Использовать
    снова"/"Использовать N км". `target` - message.answer или
    callback_query.message.answer (у обоих одинаковая сигнатура)."""
    state['courier_finance_draft'] = draft
    step = draft['step']

    if step == 'km':
        # Если сегодня уже есть завершённые смены (см. "✅ НАЧАТЬ СМЕНУ"/
        # "⏹ ЗАВЕРШИТЬ СМЕНУ") - подставляем км/часы автоматически и сразу
        # переходим дальше, без лишнего вопроса (по просьбе пользователя,
        # 20.09.2026: "километраж... берётся из данных по кнопке начала
        # смены"). Если данных нет - явно предлагаем ввести самостоятельно.
        totals = today_shift_totals(user_id)
        if totals['km'] > 0 or totals['minutes'] > 0:
            draft['data']['km'] = totals['km']
            draft['data']['hours'] = round(totals['minutes'] / 60, 2)
            draft['data']['airport_wait_minutes'] = totals['airport_wait_minutes']
            draft['step'] = 'consumption'
            state['courier_finance_draft'] = draft
            wait_note = ""
            if totals['airport_wait_minutes'] > 0:
                wait_note = f"\n⏳ Из них простой у аэропорта: {format_shift_duration(totals['airport_wait_minutes'])}"
            await target(
                f"🚗 Из сегодняшних смен: *{totals['km']:.1f} км*, "
                f"*{format_shift_duration(totals['minutes'])}* за рулём.{wait_note}\n\n"
                "Данные взяты автоматически - если что-то не так, можешь поправить позже.",
                parse_mode='Markdown',
            )
            await advance_finance_step(target, user_id, state, draft)
            return
        await target(
            "🚗 За сегодня нет данных по сменам (кнопка «✅ НАЧАТЬ СМЕНУ» не нажималась) - "
            + COURIER_FINANCE_STEP_PROMPTS['km'],
            reply_markup=courier_finance_cancel_keyboard(),
        )
        return

    if step == 'car_ownership':
        # Спрашивается один раз и запоминается (см. CAR_OWNERSHIP_OWN/
        # CAR_OWNERSHIP_RENTED) - если уже известно, сразу подставляем и
        # переходим дальше без лишнего вопроса; отдельно предлагаем сменить.
        defaults = finance_defaults(state)
        remembered = defaults.get('car_ownership')
        if remembered is not None:
            draft['data']['car_ownership'] = remembered
            if remembered == CAR_OWNERSHIP_RENTED:
                draft['step'] = 'rent'
            else:
                draft['data']['rent'] = 0.0
                draft['step'] = 'expenses'
            state['courier_finance_draft'] = draft
            await target(
                f"🚘 Машина: *{CAR_OWNERSHIP_LABELS[remembered]}* (как в прошлый раз).",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(text="🔄 Сменить", callback_data="finance_car_change"),
                ]]),
                parse_mode='Markdown',
            )
            await advance_finance_step(target, user_id, state, draft)
            return
        await target(COURIER_FINANCE_STEP_PROMPTS['car_ownership'], reply_markup=car_ownership_keyboard())
        return

    if step in FINANCE_REMEMBERED_FIELDS:
        defaults = finance_defaults(state)
        remembered = defaults.get(step)
        if remembered is not None:
            label = FINANCE_FIELD_LABELS[step](remembered)
            await target(
                f"{COURIER_FINANCE_STEP_PROMPTS[step]}\n\n_Прошлый раз: {label}_",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(text=f"✅ Использовать снова: {label}", callback_data=f"finance_use_default_{step}"),
                ]]),
                parse_mode='Markdown',
            )
            await target("Или введи новое значение сообщением:", reply_markup=courier_finance_cancel_keyboard())
            return
        await target(COURIER_FINANCE_STEP_PROMPTS[step], reply_markup=courier_finance_cancel_keyboard())
        return

    await target(COURIER_FINANCE_STEP_PROMPTS[step], reply_markup=courier_finance_cancel_keyboard())

FINANCE_FIELD_LABELS = {
    'consumption': lambda v: f"{v:g} л/100км",
    'fuel_price': lambda v: f"{v:g} ₽/л",
    'rent': lambda v: f"{v:g} ₽" if v else "нет аренды",
    'tax_rate': lambda v: f"{v:g}%",
}

FINANCE_STEP_ORDER = {
    'income': 'km',
    'km': 'consumption',
    'consumption': 'fuel_price',
    'fuel_price': 'car_ownership',
    'rent': 'expenses',
    'expenses': 'tax_rate',
    'tax_rate': 'hours',
}

@router.callback_query(lambda c: c.data.startswith("finance_use_default_"))
async def use_finance_default(callback_query: types.CallbackQuery):
    """Кнопка "✅ Использовать снова: ..." на шагах расхода топлива/цены
    топлива/аренды/налога - подставляет запомненное с прошлого раза значение
    (см. FINANCE_REMEMBERED_FIELDS/remember_finance_default) вместо
    повторного ввода (по просьбе пользователя, 20.09.2026)."""
    await callback_query.answer()
    field = callback_query.data[len("finance_use_default_"):]
    user_id = callback_query.from_user.id
    state = user_state.get(user_id)
    draft = state.get('courier_finance_draft') if state else None
    if not draft or draft.get('step') != field:
        await callback_query.message.edit_reply_markup(reply_markup=None)
        return
    value = finance_defaults(state).get(field)
    if value is None:
        return
    draft['data'][field] = value
    draft['step'] = FINANCE_STEP_ORDER[field]
    state['courier_finance_draft'] = draft
    await callback_query.message.edit_text(f"✅ Использовано: {FINANCE_FIELD_LABELS[field](value)}")
    await advance_finance_step(callback_query.message.answer, user_id, state, draft)

@router.callback_query(lambda c: c.data in ("finance_car_own", "finance_car_rented"))
async def set_car_ownership(callback_query: types.CallbackQuery):
    """Кнопки "🔧 Своя / кредит / лизинг" / "🔑 В аренде" на шаге
    'car_ownership' (по просьбе пользователя, 20.09.2026: "если машина в
    аренде то 10% не учитывай а если личная или кредит лизинг то учитывай")
    - запоминает выбор как профиль (см. FINANCE_REMEMBERED_FIELDS) и решает,
    нужен ли отдельный шаг "Аренда ТС за день" дальше: своя/кредит/лизинг -
    аренды нет (rent=0), в аренде - спрашиваем сумму."""
    await callback_query.answer()
    ownership = CAR_OWNERSHIP_OWN if callback_query.data == "finance_car_own" else CAR_OWNERSHIP_RENTED
    user_id = callback_query.from_user.id
    state = user_state.get(user_id)
    draft = state.get('courier_finance_draft') if state else None
    if not draft or draft.get('step') != 'car_ownership':
        await callback_query.message.edit_reply_markup(reply_markup=None)
        return
    draft['data']['car_ownership'] = ownership
    remember_finance_default(state, 'car_ownership', ownership)
    if ownership == CAR_OWNERSHIP_RENTED:
        draft['step'] = 'rent'
    else:
        draft['data']['rent'] = 0.0
        draft['step'] = 'expenses'
    state['courier_finance_draft'] = draft
    await callback_query.message.edit_text(f"✅ Машина: {CAR_OWNERSHIP_LABELS[ownership]}")
    await advance_finance_step(callback_query.message.answer, user_id, state, draft)

@router.callback_query(lambda c: c.data == "finance_car_change")
async def change_car_ownership(callback_query: types.CallbackQuery):
    """Кнопка "🔄 Сменить" под автоподставленным типом машины (см.
    advance_finance_step, шаг 'car_ownership') - откатывает черновик назад
    к явному вопросу, если запомненное значение сейчас неверно (например,
    водитель пересел с личной машины на арендованную)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state.get(user_id)
    draft = state.get('courier_finance_draft') if state else None
    if not draft:
        await callback_query.message.edit_reply_markup(reply_markup=None)
        return
    draft['step'] = 'car_ownership'
    draft['data'].pop('car_ownership', None)
    draft['data'].pop('rent', None)
    state['courier_finance_draft'] = draft
    await callback_query.message.edit_reply_markup(reply_markup=None)
    await callback_query.message.answer(COURIER_FINANCE_STEP_PROMPTS['car_ownership'], reply_markup=car_ownership_keyboard())

@router.message(lambda message: user_state.get(message.from_user.id, {}).get('courier_finance_draft') is not None)
async def courier_finance_flow(message: types.Message):
    """Пошаговый сбор данных для финансового калькулятора - та же схема, что
    у shared_order_flow (черновик в state, один вопрос за раз). Должен стоять
    РАНЬШЕ общих текстовых хендлеров по той же причине (см. shared_order_flow).

    Порядок шагов (по просьбе пользователя, 20.09.2026): доход -> км (авто из
    смены, если есть) -> расход топлива -> цена топлива -> аренда/лизинг ТС
    -> доп. расходы за день -> налог (по умолчанию 6% от дохода) -> часы
    (авто из смены). Расход топлива/цена топлива/аренда/налог запоминаются
    и на следующий раз предлагаются кнопкой "Использовать снова" (см.
    FINANCE_REMEMBERED_FIELDS)."""
    user_id = message.from_user.id
    state = user_state[user_id]
    draft = state['courier_finance_draft']
    text = (message.text or '').strip()

    if text == "❌ Отмена":
        state.pop('courier_finance_draft', None)
        await message.answer("Расчёт отменён.", reply_markup=courier_module_keyboard(state.get('category')))
        return

    step = draft['step']

    if step == 'income':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял сумму - введи просто число, например 2340:")
            return
        draft['data']['income'] = value
        draft['step'] = 'km'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'km':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял километраж - введи число, например 87:")
            return
        draft['data']['km'] = value
        draft['step'] = 'consumption'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'consumption':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял расход - введи число, например 6.2:")
            return
        draft['data']['consumption'] = value
        remember_finance_default(state, 'consumption', value)
        draft['step'] = 'fuel_price'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'fuel_price':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял цену топлива - введи число, например 61.5:")
            return
        draft['data']['fuel_price'] = value
        remember_finance_default(state, 'fuel_price', value)
        draft['step'] = 'car_ownership'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'rent':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял сумму - введи число (или 0, если по факту не платил сегодня):")
            return
        draft['data']['rent'] = value
        remember_finance_default(state, 'rent', value)
        draft['step'] = 'expenses'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'car_ownership':
        # Шаг только на инлайн-кнопках (см. set_car_ownership) - случайный
        # текст сюда игнорируем, повторяем вопрос кнопками.
        await message.answer(COURIER_FINANCE_STEP_PROMPTS['car_ownership'], reply_markup=car_ownership_keyboard())
        return

    if step == 'expenses':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer("Не понял сумму - введи число (или 0, если доп. расходов не было):")
            return
        draft['data']['expenses'] = value
        draft['step'] = 'tax_rate'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'tax_rate':
        value = parse_decimal(text)
        if value is None or value < 0:
            await message.answer(f"Не понял ставку - введи число, например {DEFAULT_TAX_RATE_PERCENT:g}:")
            return
        draft['data']['tax_rate'] = value
        remember_finance_default(state, 'tax_rate', value)
        draft['step'] = 'hours'
        await advance_finance_step(message.answer, user_id, state, draft)
        return

    if step == 'hours':
        value = parse_decimal(text)
        if value is None or value <= 0:
            await message.answer("Не понял часы - введи число больше нуля, например 5.5:")
            return
        draft['data']['hours'] = value
        state.pop('courier_finance_draft', None)
        await send_courier_finance_result(message, user_id, draft['data'])
        return

async def send_courier_finance_result(message: types.Message, user_id, data):
    """Считает и показывает итог дня, сохраняет доход/чистыми в отдельную
    таблицу статистики (см. save_finance_result/finance_history) - формула:
    доход минус топливо минус резерв на износ (10%, только если машина СВОЯ
    или в кредите/лизинге - см. CAR_OWNERSHIP_OWN/CAR_OWNERSHIP_RENTED)
    минус аренда минус доп. расходы минус налог (% от ВАЛОВОГО дохода) =
    чистыми; отдельной строкой ₽/час."""
    income = data['income']
    km = data['km']
    consumption = data['consumption']
    fuel_price = data['fuel_price']
    rent = data.get('rent', 0.0)
    expenses = data['expenses']
    tax_rate = data.get('tax_rate', DEFAULT_TAX_RATE_PERCENT)
    hours = data['hours']
    airport_wait_minutes = data.get('airport_wait_minutes', 0)
    car_ownership = data.get('car_ownership', CAR_OWNERSHIP_OWN)

    # По просьбе пользователя (20.09.2026): "если машина в аренде то 10% не
    # учитывай а если личная или кредит лизинг то учитывай" - износ/ремонт
    # арендованной машины несёт арендодатель, а не водитель.
    is_rented = car_ownership == CAR_OWNERSHIP_RENTED
    fuel_cost = (km / 100) * consumption * fuel_price
    wear_reserve = 0.0 if is_rented else income * COURIER_WEAR_RESERVE_RATE
    tax_amount = income * (tax_rate / 100)
    net_profit = income - fuel_cost - wear_reserve - rent - expenses - tax_amount
    per_hour = net_profit / hours

    def fmt(n):
        return f"{n:,.0f}".replace(',', ' ')

    # По просьбе пользователя (20.09.2026): показываем, какие именно данные
    # были учтены в расчёте - все введённые/подставленные цифры одним
    # компактным блоком в начале сообщения, перед разбивкой по статьям.
    # Визуальное оформление (20.09.2026, "сделай красивое оформление") -
    # точечный разделитель между блоками, итог в рамке из ▓ для акцента.
    lines = [
        "📊 *ДЕНЬ — ИТОГ*",
        WHERE_TO_GO_DIVIDER,
        "_Учтено в расчёте:_",
        f"💰 Доход: {fmt(income)} ₽",
        f"🛣 Пробег: {fmt(km)} км  ·  ⛽ {consumption:g} л/100км × {fuel_price:g} ₽/л",
        f"🚘 Машина: {CAR_OWNERSHIP_LABELS.get(car_ownership, CAR_OWNERSHIP_LABELS[CAR_OWNERSHIP_OWN])}",
    ]
    if rent > 0:
        lines.append(f"🔑 Аренда ТС: {fmt(rent)} ₽")
    lines.append(f"📦 Доп. расходы: {fmt(expenses)} ₽  ·  🧾 Налог: {tax_rate:g}%")
    time_line = f"🕐 За рулём: {hours:g} ч"
    if airport_wait_minutes > 0:
        time_line += f"  ·  ⏳ простой у аэропорта: {format_shift_duration(airport_wait_minutes)}"
    lines.append(time_line)
    lines.append(WHERE_TO_GO_DIVIDER)
    lines.extend([
        f"Валовый доход: {fmt(income)} ₽",
        f"⛽ Топливо: −{fmt(fuel_cost)} ₽",
    ])
    if is_rented:
        lines.append("🔧 Резерв на износ/ремонт: не учтён _(машина в аренде)_")
    else:
        lines.append(f"🔧 Резерв на износ/ремонт (10%): −{fmt(wear_reserve)} ₽")
    if rent > 0:
        lines.append(f"🚘 Аренда ТС: −{fmt(rent)} ₽")
    if expenses > 0:
        lines.append(f"📦 Доп. расходы: −{fmt(expenses)} ₽")
    lines.append(f"🧾 Налог ({tax_rate:g}%): −{fmt(tax_amount)} ₽")
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")
    lines.append(f"✅ *Чистыми за день: {fmt(net_profit)} ₽*")
    lines.append(f"_≈ {fmt(per_hour)} ₽/ч за {hours:g} ч_")
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")

    category = user_state.get(user_id, {}).get('category')
    await message.answer('\n'.join(lines), reply_markup=courier_module_keyboard(category), parse_mode='Markdown')
    save_finance_result(user_id, income, net_profit)

CITY_MAP = {
    "🏛️ Москва": "moscow", "🕯️ СПб": "spb", "🌲 Новосибирск": "novosibirsk",
    "🏔️ Екатеринбург": "ekb", "🎓 Казань": "kazan", "❄️ Челябинск": "chelyabinsk",
    "🌾 Омск": "omsk", "🏭 Самара": "samara", "🌊 Ростов": "rostov",
    "🏰 Нижний Новгород": "nnovgorod", "🌴 Краснодар": "krasnodar", "🏖️ Сочи": "sochi"
}

@router.message(lambda message: message.text in CITY_MAP)
async def select_city(message: types.Message):
    """ВАЖНО: фильтр - точное совпадение с текстом кнопки из city_keyboard()
    (message.text in CITY_MAP), а НЕ проверка "название города - подстрока
    где-то в тексте сообщения" (было раньше - any(city in message.text ...)).
    Раньше это означало, что город мог неожиданно смениться на любом экране,
    если пользователь просто написал в чат что-то, содержащее название
    города как часть текста - по просьбе пользователя город теперь меняется
    ТОЛЬКО явным нажатием кнопки на экране выбора города (после /start или
    "🏙 Выбор города", см. send_start_screen) - больше нигде и никогда сам не
    "слетает". Фолбэк на "moscow" по умолчанию тоже убран - раз попадание
    сюда теперь возможно только по точному совпадению кнопки из CITY_MAP,
    city_map.get(...) всегда находит город, запасной вариант был не нужен и
    маскировал бы реальную ошибку, если бы вдруг не нашёл."""
    city = CITY_MAP[message.text]
    user_state[message.from_user.id] = {'city': city}
    text = f"✅ *{message.text}*\n━━━━━━━━━━━━━━━━━━\n\n🚕 Выбери свою категорию 👇"
    await message.answer(text, reply_markup=category_keyboard(), parse_mode='Markdown')

@router.message(lambda message: any(cat_data['name'] in message.text for cat_data in CATEGORIES.values()))
async def select_category(message: types.Message):
    user_id = message.from_user.id
    if user_id not in user_state:
        await message.answer("Сначала выбери город!")
        return
    # Сортируем по длине названия по убыванию - иначе "ТАКСИ" (подстрока
    # "ТАКСИ ULTIMA") матчится раньше и категория Ultima никогда не выбирается
    selected_category = None
    for cat_key, cat_data in sorted(CATEGORIES.items(), key=lambda kv: -len(kv[1]['name'])):
        if cat_data['name'] in message.text:
            user_state[user_id]['category'] = cat_key
            selected_category = cat_key
            break
    cat_label = CATEGORIES.get(selected_category, {}).get('name', '')
    text = f"✅ *{cat_label}*\n━━━━━━━━━━━━━━━━━━\n\n🧰 Выбери, что нужно 👇"
    await message.answer(text, reply_markup=services_keyboard(selected_category, user_state[user_id].get('city'), user_id), parse_mode='Markdown')

    # По просьбе пользователя - сразу после выбора категории предлагаем
    # включить "Очередь у аэропорта" (для тех категорий, кому она вообще
    # видна - см. CATEGORIES_WITHOUT_AIRPORTS), чтобы бот корректно отображал
    # очередь с первой же поездки, а не только если водитель сам вспомнит
    # про эту кнопку внутри "Инструменты водителя". Кнопка "Включить сейчас"
    # сразу активирует отслеживание (enable_airport_queue_tracking) - см.
    # enable_airport_queue_now ниже.
    # Не предлагаем повторно, если трансляция живой геопозиции для этого
    # пользователя УЖЕ идёт (по жалобе пользователя, 20.09.2026: "сверху уже
    # включен сбор локации... а он опять запрашивает") - проверяем не только
    # свои флаги (_location_tracking_active), но и просто свежий пинг
    # геопозиции (get_fresh_live_location), т.к. водитель мог включить
    # трансляцию сам, ещё до выбора категории, без кнопок бота (см.
    # handle_passive_live_location) - тогда наши фичи формально не активны,
    # но Telegram уже шлёт пинги, и просить включить ещё раз незачем.
    #
    # ГОНКА СОСТОЯНИЙ (повторная жалоба пользователя, 20.09.2026, со
    # скриншотом): если водитель включил трансляцию буквально за секунду до
    # выбора категории, Telegram ещё не успел прислать боту первый пинг
    # геопозиции - на момент этой проверки get_fresh_live_location ещё
    # пустой, хотя трансляция уже идёт. Короткая пауза перед проверкой даёт
    # первому пингу шанс дойти и попасть в user_state ДО того, как решаем,
    # показывать подсказку или нет.
    await asyncio.sleep(2)
    if (
        selected_category
        and selected_category not in CATEGORIES_WITHOUT_AIRPORTS
        and not _location_tracking_active(user_id)
        and not get_fresh_live_location(user_id)
    ):
        # По прямой просьбе пользователя (21.09.2026, повторная жалоба
        # "опять очередь у аэропорта выключена по умолчанию"): раньше
        # реактивация пропускалась, если пользователь когда-либо явно
        # выключал эту настройку (ключ 'airport_queue_active' уже был False
        # в state) - идея была уважать явный отказ. На практике это привело
        # к тому, что у части пользователей флаг застрял в False ещё ДО
        # фикса хранения БД на Railway Volume (см. блок "БАГФИКС" у DB_FILE
        # выше) и оставался таким навсегда, даже после явного подтверждения
        # "никогда сам не выключал". По прямому уточнению пользователя -
        # теперь включаем безусловно при каждом выборе категории (тем же
        # способом, что и раньше был единственный путь до этого уточнения),
        # без проверки предыдущего состояния - водитель всегда может
        # выключить вручную в Настройках, если не нужно именно сейчас.
        enable_airport_queue_tracking(user_id)
        suggest_text = (
            "📍 Отслеживание очереди у аэропорта уже включено. Осталось только поделиться "
            "живой геопозицией в Telegram - тогда уведомления о подъезде к аэропорту "
            "и времени ожидания будут приходить автоматически."
        )
        suggest_kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="📍 Как включить трансляцию", callback_data="airport_queue_enable_now")]
        ])
        await message.answer(suggest_text, reply_markup=suggest_kb)

@router.callback_query(lambda c: c.data == "airport_queue_enable_now")
async def enable_airport_queue_now(callback_query: types.CallbackQuery):
    """Кнопка "📍 Включить сейчас" на подсказке сразу после выбора категории
    (см. select_category выше) - включает отслеживание, не заставляя
    водителя идти искать кнопку в "Инструменты водителя" отдельно."""
    user_id = callback_query.from_user.id
    state = user_state.get(user_id)
    if not state or state.get('category') in CATEGORIES_WITHOUT_AIRPORTS:
        await callback_query.answer()
        return
    await callback_query.answer("Включено")
    enable_airport_queue_tracking(user_id)
    await callback_query.message.answer(airport_queue_enable_text(), parse_mode='Markdown')

@router.message(lambda message: message.text == "🌤 Погода")
async def show_weather_forecast(message: types.Message):
    """Ручной просмотр погоды по своему городу - почасовая разбивка (вид
    осадков + температура) на RAIN_FORECAST_HOURS часов вперёд. Второй режим
    фичи - помимо автопуша на скорое начало/усиление осадков (см.
    push_rain_alert/rain_checker выше). Тот же источник (Open-Meteo), что и
    у фоновой проверки, просто без записи состояния в БД - разовый запрос
    по кнопке."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    category = state.get('category')
    if not city or city not in RAIN_CITY_COORDS:
        await message.answer("Сначала выбери город 🏙")
        return
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    forecast = await fetch_rain_forecast(city)
    text = format_weather_forecast_text(city_name, forecast)
    await message.answer(text, parse_mode='Markdown', reply_markup=services_keyboard(category, city, user_id))

